/* Exam 1 glossary — PHAR 4344, Dr. Gottlieb, Days 1–5 (9/22–9/29).
   Definitions come from the lecture decks and transcripts (slide wording first;
   his spoken wording in hook/quote where the two differ). Slide numbers marked ~
   were counted from the deck text and may be off by one or two.
   Groups: 'Drug basics', 'Drug–receptor binding', 'Drug classes',
   'Dose–response curves', 'Receptors and signaling'.
   Figure keys: drc-basic, potency, efficacy, partial, inverse, competitive,
   irreversible, binding-kd, sites, two-state, gpcr, spare. */
const TERMS = [

/* ---------------- Drug basics ---------------- */
{id:'pharmacology', term:'Pharmacology', lecture:'L01', group:'Drug basics',
 def:'The whole field (pharmacokinetics plus pharmacodynamics): the study of the interaction of drugs with biological systems: which drug, what it does and where, and how much (the smallest dose that gives the desired effect). It determines mechanisms of action, dose–response relationships, therapeutic dose, potency, minimal and maximal effect, and safety.',
 hook:'The pharmacology diagram splits it in two: pharmacokinetics (absorption, distribution, metabolism, excretion) and pharmacodynamics (drug–receptor signaling that gives the physiological response).',
 gist:'The whole field: what the drug does and how much reaches it.',
 scene:'A diagram splits the subject in two: one half is absorption, distribution, metabolism and excretion, the other is the drug meeting its receptor and producing the physiological response.',
 confuse:['pharmacodynamics','pharmacokinetics'],
 quote:'Pharmacology: “the study of the interaction of “Drugs” with biological systems” ... Which, What, & Where? How much? Smallest dose => Desired effect?',
 cite:'Pharmacodynamics-Day-1-2026s.pdf slides ~21–~22; transcript 9/22',
 src:'both'},

{id:'pharmacodynamics', term:'Pharmacodynamics (PD)', lecture:'L02', group:'Drug basics',
 def:'The study of the biochemical and physiological effects of drugs and their mechanisms of action. General rules: the drug must reach the site of action, must bind to and interact with a receptor, and does not create anything but changes the ongoing physiological system.',
 hook:'Spoken definition: “the study of how drugs interact with the biological system.” Its two basic concepts are affinity and efficacy.',
 gist:'How the drug interacts with the biological system: affinity and efficacy only.',
 scene:'Metoprolol reaches the heart, binds the β1 receptor and blocks it, and the heart rate falls; nothing new is created, an ongoing process is changed.',
 confuse:['pharmacokinetics','pharmacology'],
 quote:'General rules: 1) Drug must reach the site of action 2) Drug must bind to and interact with a receptor 3) Drug do not create anything, but change the ongoing phys. system',
 cite:'Pharmacodynamics-Day_2_2026s copy.pdf slide ~31; Pharmacodynamics-Day-1-2026s.pdf slide ~22; transcript 9/23',
 src:'both'},

{id:'pharmacokinetics', term:'Pharmacokinetics (PK)', lecture:'L01', group:'Drug basics',
 def:'The absorption, distribution, metabolism and excretion (ADME) side of the pharmacology diagram: how much of the drug gets to the site of action. It sets the apparent potency of a drug (age, absorption, distribution, elimination, drug–drug interactions).',
 hook:'On the efficacy poll, “the ability of a drug to be absorbed at the level of the GI” is pharmacokinetics, not efficacy.',
 gist:'Absorption, distribution, metabolism, excretion: how much drug gets to the site of action.',
 scene:'A drug is swallowed, absorbed in the gut, broken down by the liver on first pass, and only a fraction reaches the receptor; given intravenously, 100% is available.',
 confuse:['pharmacodynamics','apparent-potency'],
 quote:'So pharmokinetics is going to be affecting how much of the drug gets to the site of action. Because that’s how it’s going to produce its effects.',
 cite:'Pharmacodynamics-Day-1-2026s.pdf slides ~22–~23, ~27; transcript 9/22',
 src:'both'},

{id:'drug', term:'Drug', lecture:'L01', group:'Drug basics',
 def:'A chemical substance that alters an ongoing physiological or pathological function by interacting with components of a biological system. Drugs initiate, inhibit or modulate a response; they do not create anything new.',
 hook:'Walter Straub: there is only a quantitative difference between a drug and a poison (vitamin A in carrots vs polar bear liver).',
 gist:'A chemical that changes an ongoing function; enhances or suppresses, creates nothing new.',
 scene:'Metoprolol does not create a new heartbeat; it slows the rate the heart was already producing. Vitamin A in a carrot helps night blindness and in a polar bear liver poisons: only the amount differs.',
 confuse:['ligand','nds'],
 quote:'drugs don’t create anything new, they just change whatever is happening in the body. Either they are going to enhance the signal or perhaps suppress the signal',
 cite:'Pharmacodynamics-Day-1-2026s.pdf slides ~29–~31; transcript 9/22',
 src:'both'},

{id:'receptor', term:'Receptor', lecture:'L01', group:'Drug basics',
 def:'Regulatory proteins involved in the transfer of chemical information carried by endogenous or exogenous mediators. Classified by the structure of the receptor protein and its transduction components: ion channels, 7-transmembrane (GPCR), 1-transmembrane (tyrosine kinases) and intracellular/nuclear receptors.',
 hook:'His picture: the gatekeeper that senses hormones, neurotransmitters and drugs; the message the receptor creates is the physiological response. Receptors come in two flavors, active or inactive.',
 gist:'The regulatory protein that senses hormones, neurotransmitters and drugs; it is active or inactive.',
 scene:'A protein in the heart cell membrane recognizes norepinephrine by its shape and size, changes its conformation, and the cell answers with a faster beat. The same protein also binds metoprolol.',
 confuse:['ligand','effector','transducer'],
 quote:'Receptors are regulatory proteins involved in the transfer of chemical information carried by various endogenous/exogenous mediators',
 cite:'Pharmacodynamics-Day-1-2026s.pdf slides ~11, ~34–~36; transcript 9/22',
 src:'both'},

{id:'ligand', term:'Ligand', lecture:'L03', group:'Drug basics',
 def:'A chemical that a receptor recognizes and binds by its shape, size and other properties: endogenous (a hormone or neurotransmitter) or exogenous (a drug, a supplement, something eaten or drunk). A ligand induces a conformational change in the receptor.',
 hook:'Multiple chemicals may bind the same receptor, and one chemical may bind multiple receptors (acetylcholine at nicotinic and muscarinic). Ligand-gated channels are named for it.',
 gist:'Any chemical a receptor recognizes and binds: hormone, neurotransmitter, drug, supplement, food.',
 scene:'Acetylcholine made by the body and nicotine from a cigarette both bind the nicotinic receptor; acetylcholine also binds the muscarinic receptor.',
 confuse:['drug','receptor'],
 quote:'Cells have receptors that recognize specific chemicals ... Endogenous as well as exogenous',
 cite:'Pharmacodynamics-Day_3_2026s.pdf slides ~26, ~30; transcript 9/23; transcript 9/24',
 src:'both'},

{id:'moa', term:'Mechanism of action (MOA)', lecture:'L01', group:'Drug basics',
 def:'What the drug does at its receptor: which receptor it binds and whether it activates, inhibits or just binds (e.g., metoprolol: reversible β1 receptor antagonist). The must-know for every drug on Exam 1.',
 hook:'MOA is must-know; site of action (SOA) is should-know; effect, ADR and DDI are predicted from the two. Use, dose, route and brand names are not tested.',
 gist:'Which receptor the drug binds and what it does there: activates, inhibits, binds.',
 scene:'For metoprolol the first thing written down is reversible β1 receptor antagonist: which receptor it binds and that it blocks it, before anything about where those receptors are.',
 confuse:['soa'],
 quote:'So which receptor is binding to you, what is it doing to that receptor when it’s bound, is it activating, inhibiting, just binding, where is the receptor located',
 cite:'Pharmacodynamics-Day-1-2026s.pdf slides ~7–~9, ~12, ~33; transcript 9/22',
 src:'both'},

{id:'soa', term:'Site of action (SOA)', lecture:'L01', group:'Drug basics',
 def:'Where the receptor the drug acts on is located (metoprolol: heart, kidneys and brain; thiazides: distal convoluted tubule). Knowing MOA plus SOA lets you predict the effect, side effects and drug–drug interactions without memorizing them.',
 hook:'Classifying a drug by chemical structure (benzothiadiazine ring) predicts little; MOA plus SOA (Na+/Cl− symporter antagonist at the distal tubule) predicts diuresis and hyponatremia.',
 gist:'Where the receptor is located; with the mechanism, it predicts effect and side effects.',
 scene:'Metoprolol blocks β1 receptors, and those receptors are in the heart, the kidneys and the brain; from the location alone you expect bradycardia and fatigue without memorizing them.',
 confuse:['moa'],
 quote:'The things that you should know are going to be the sites of actions. Because if you know where the receptor is located and you know what it does to the receptor, now you can predict the effect, the side effect, the drug-drug interaction, contraindication, use.',
 cite:'Pharmacodynamics-Day-1-2026s.pdf slides ~7, ~9, ~33; transcript 9/22',
 src:'both'},

{id:'nds', term:'Natural dietary supplement (NDS)', lecture:'L01', group:'Drug basics',
 def:'A product regulated as food, not as a drug, so with less FDA oversight; it stays on the market until it causes harm. Its label cannot state that it treats, cures, diagnoses or prevents disease, and natural does not mean safe or free of drug interactions.',
 hook:'Every option on his NDS poll was incorrect: labels cannot claim cure, the FDA does not test them like prescription drugs, centuries of use does not prove safety and effectiveness, and herbals interact with prescription/OTC drugs.',
 gist:'Regulated as food, not as a drug; the label cannot claim to cure.',
 scene:'A bottle of fish oil sits on the shelf as food, not tested like a prescription, and stays there until it causes harm; the label may not say it treats or cures anything.',
 confuse:['drug'],
 quote:'Dietary supplements regulated as food ... Not Drugs (Less FDA oversight) ... until they cause harm',
 cite:'Pharmacodynamics-Day-1-2026s.pdf slides ~15–~16, ~18, ~20; transcript 9/22',
 src:'both'},

{id:'selectivity', term:'Selectivity', lecture:'L01', group:'Drug basics',
 def:'How narrowly a drug binds one receptor type rather than others: loratadine is a selective H1 inverse agonist; diphenhydramine binds H1, H2 and muscarinic receptors and is very non-selective. The less selective a drug is, the more effects and side effects it produces.',
 hook:'The larger the dose gets, the less selective a drug becomes (metoprolol is β1-selective up to about 200 mg, then affects β2). Selectivity is about which receptors are bound; affinity is how tightly.',
 gist:'How few receptor types a drug binds; fewer types, fewer side effects.',
 scene:'Loratadine binds only the H1 receptor; diphenhydramine binds H1, H2 and muscarinic receptors and produces many more effects. Metoprolol binds only β1 up to about 200 mg, then β2 as well.',
 confuse:['affinity','potency'],
 quote:'the larger the dose gets, the less selective a drug becomes ... Metoprolol is a beta 1 selective up to about 200 mg. Once you go above 200, you start to affect the beta 2s, so you start to lose selectivity',
 cite:'Pharmacodynamics-Day-1-2026s.pdf slides ~21, ~29; transcript 9/22; transcript 9/24',
 src:'both'},

/* ---------------- Drug–receptor binding ---------------- */
{id:'affinity', term:'Affinity', lecture:'L02', group:'Drug–receptor binding',
 def:'The attraction of a ligand for the receptor: how likely a drug is to bind and stay bound. It depends on the molecular forces (bonds) the drug forms with the receptor and is measured by Kd: the smaller the Kd, the greater the affinity.',
 hook:'Affinity is read on the x-axis (further left = higher affinity); efficacy on the y-axis. Poll trap: “the ability of a drug to bind and stay bound to a receptor” is affinity, not efficacy.',
 gist:'How likely a drug binds and stays bound; depends on the bonds formed.',
 scene:'Phenoxybenzamine forms a covalent bond with the α1 receptor and stays bound; prazosin forms weaker bonds and comes off. On a binding curve, the drug furthest left binds 50% of receptors at the smallest dose.',
 confuse:['efficacy','potency','kd'],
 fig:'binding-kd',
 quote:'Remember, affinity is how likely a drug is to bind and stay bound to a receptor, and the binding of a drug to the receptor is going to be depending on what type of bonds they form covalent bonds, hydrogen bonds, ion bonds.',
 cite:'Pharmacodynamics-Day_2_2026s copy.pdf slides ~31, ~55; Pharmacodynamics-Day-1-2026s.pdf slides ~21, ~37; transcript 9/22; transcript 9/23',
 src:'both'},

{id:'efficacy', term:'Efficacy (intrinsic efficacy)', lecture:'L02', group:'Drug–receptor binding',
 def:'The property of a molecule that causes the receptor to change its behavior: the ability of the drug to change the receptor state, active to inactive or inactive to active. Positive efficacy activates receptors, negative efficacy shuts them down, and zero efficacy is a neutral antagonist.',
 hook:'Read on the y-axis as the height of the curve (Emax). Efficacy cannot be calculated directly; it is a relative measurement between ligands.',
 gist:'The ability to change the receptor state; positive activates, negative shuts down.',
 scene:'Norepinephrine binds β1 and flips it from inactive to active, loratadine binds H1 and flips it from active to inactive, and metoprolol binds β1 without changing its state.',
 confuse:['affinity','intrinsic-activity','potency'],
 fig:'efficacy',
 quote:'Efficacy is the ability of that drug to change the receptor behavior. It’s activity, its state from active to inactive or inactive to active, right?',
 cite:'Pharmacodynamics-Day_2_2026s copy.pdf slide ~31; Pharmacodynamics-Day_3_2026s.pdf slides ~19, ~26; Pharmacodynamics-Day-1-2026s.pdf slide ~38; transcript 9/22; transcript 9/23',
 src:'both'},

{id:'intrinsic-activity', term:'Intrinsic activity', lecture:'L03', group:'Drug–receptor binding',
 def:'A number for the ability of a drug to produce a response: full agonist = 100% (1), partial agonist 1–99% (0.01–0.99), antagonist = 0. It does not count the tissue (how many receptors are present), so efficacy is the term used instead.',
 hook:'It does not account for the tissue (how many receptors are present), so it is incomplete; efficacy is the more comprehensive term. The names and the formula are not tested.',
 gist:'A number: full agonist 1, partial 0 to 1, antagonist 0; ignores the tissue.',
 scene:'Ariëns assigned each drug a single value, norepinephrine 1, albuterol somewhere from 1% to 99%, metoprolol 0, without counting how many receptors the tissue has, so the theory is incomplete.',
 confuse:['efficacy'],
 quote:'What he did not count was for the tissue, how many receptors are present in that system. So this is an incomplete theory that we can’t really use much',
 cite:'Pharmacodynamics-Day_3_2026s.pdf slides ~24–~26; Pharmacodynamics-Day-1-2026s.pdf slide ~28; transcript 9/22; transcript 9/24',
 src:'both'},

{id:'kd', term:'Kd (dissociation constant)', lecture:'L02', group:'Drug–receptor binding',
 def:'The drug concentration that binds 50% of the available binding sites (also written Ki, Ka). From the law of mass action it equals K2/K1, the rate of dissociation over the rate of association. The smaller it is, the greater the affinity: inversely proportional.',
 hook:'Read on the x-axis of a binding curve; it says nothing about effect. Convert units before comparing (milli 10^-3, micro 10^-6, nano 10^-9): “the units ... about 10% of you are gonna miss it.”',
 gist:'The concentration binding 50% of receptors; smaller means greater affinity, says nothing of effect.',
 scene:'For the β1 receptor drug A has a value of 30 micromolar and drug B 100 nanomolar; after converting the units the smaller number means drug B binds half of the receptors at a lower concentration (at M1 both are 250 nanomolar: equal affinity). Convert milli, micro and nano before comparing.',
 confuse:['ec50','affinity','mass-action'],
 fig:'binding-kd',
 quote:'So the take-home message is that the smaller the coefficient of dissociation is, the more drugs receptors are going to find together, and thus the greater the affinity is going to be.',
 cite:'Pharmacodynamics-Day_2_2026s copy.pdf slides ~45–~50; Pharmacodynamics-Day_3_2026s.pdf slide ~31; transcript 9/24',
 src:'both'},

{id:'binding-curve', term:'Binding curve (Bmax)', lecture:'L02', group:'Drug–receptor binding',
 def:'Percent of receptors bound (0% up to Bmax, 100% of the receptors) plotted against log[concentration]. Kd is the concentration at 50% bound, read on the x-axis; the curve furthest left has the smallest Kd and the highest affinity.',
 hook:'A binding curve shows binding only; a dose–response curve shows effect (Emax, EC50). Drug C “requires less dose to bind 50% of the receptors” so it has the highest affinity.',
 gist:'Percent of receptors bound versus log concentration; shows occupancy only, not effect.',
 scene:'Three drugs plotted as percent of receptors occupied, 0 up to 100, against log concentration; drug C reaches 50% occupied at the lowest dose, so it has the highest affinity. No effect is shown.',
 confuse:['drc','kd'],
 fig:'binding-kd',
 quote:'And the further the left you are, the smaller the dose is going to be required, and thus the more affinity a drug is gonna have for the receptor.',
 cite:'Pharmacodynamics-Day_2_2026s copy.pdf slide ~50; Pharmacodynamics-Day_3_2026s.pdf slide ~3; transcript 9/24',
 src:'both'},

{id:'mass-action', term:'Law of mass action', lecture:'L02', group:'Drug–receptor binding',
 def:'The rate of a chemical reaction is proportional to the concentration (mass) of the reactants: the more drug or the more receptors present, the greater the chance of binding. It is the basis of Kd and of dose responsiveness.',
 hook:'More receptors in a tissue make the same dose of norepinephrine appear more potent (curve shifts left) while its Kd, affinity and efficacy are unchanged; what changed is the tissue.',
 gist:'More drug or more receptors present, greater the chance of binding.',
 scene:'Two hearts get the same dose of norepinephrine, one with 10 receptors and one with 100; the heart with 100 responds at a lower dose, though norepinephrine itself is unchanged.',
 confuse:['kd'],
 quote:'The more I have either of the receptors or the more I have either the drug, the greater the capacity of binding to something is going to be, right?',
 cite:'Pharmacodynamics-Day_2_2026s copy.pdf slide ~45; transcript 9/24',
 src:'both'},

{id:'covalent-bond', term:'Covalent (irreversible) bond', lecture:'L02', group:'Drug–receptor binding',
 def:'Two atoms share a pair of electrons; the bond cannot be broken at body temperature and gives a long duration of action. Drugs that bind this way are called irreversible, insurmountable or non-competitive, three names for one property; ionic, hydrogen and van der Waals bonds are reversible, surmountable, competitive.',
 hook:'Aspirin, omeprazole and phenoxybenzamine form covalent bonds; a covalent binder has the highest affinity and the smallest Kd. Weak-bond drugs must fit the pocket like a hand in a glove, which is where selectivity comes from.',
 gist:'Shared pair of electrons; unbreakable at body temperature; aspirin, omeprazole, phenoxybenzamine form it.',
 scene:'Aspirin, omeprazole and phenoxybenzamine each attach to their target by sharing a pair of electrons; at body temperature the attachment cannot be broken, so the body must make new protein to recover.',
 confuse:['irreversible-antagonist','affinity'],
 quote:'They can be classified as irreversible, insurmountable, and non-competitive, which means is They all mean the same thing ... What does that mean? Once they are bound, they’re not coming off, OK?',
 cite:'Pharmacodynamics-Day_2_2026s copy.pdf slides ~15–~16; transcript 9/23; transcript 9/24',
 src:'both'},

{id:'orthosteric', term:'Orthosteric site', lecture:'L02', group:'Drug–receptor binding',
 def:'The receptor’s own binding pocket, where the endogenous agonist binds. Drugs that bind there (phenylephrine, prazosin, phenoxybenzamine at α1) compete for that one pocket, so only one can be bound at a time: either one or the other, not both.',
 hook:'Orthosteric: one or the other. Allosteric: one and the other. Spoken as “orthostatic” in the transcripts; the slide term is orthosteric.',
 gist:'The receptor’s own pocket where the endogenous agonist binds; one or the other.',
 scene:'Phenylephrine, prazosin and phenoxybenzamine all go for the same pocket on the α1 receptor, the one norepinephrine uses, so only one of them can be in it at a time.',
 confuse:['allosteric'],
 fig:'sites',
 quote:'How we define orthostatic. So they compete for the same binding pocket, right? ... with orthostatic, we can have either one or the other, not both at the same time. As with allosteric, we can have one in the other',
 cite:'Pharmacodynamics-Day_2_2026s copy.pdf slides ~18–~19; transcript 9/23; transcript 9/24',
 src:'both'},

{id:'allosteric', term:'Allosteric site / modulator', lecture:'L02', group:'Drug–receptor binding',
 def:'A different (allotopic) binding site on the receptor. A drug binding there can increase or decrease the affinity and/or efficacy of another drug for the receptor, or have no effect; it does not compete for the orthosteric pocket, so both drugs can be bound at once.',
 hook:'“Where the magic in pharmacology is”: they don’t always do things by themselves but make other drugs much better or much worse. Poll traps: allosteric agonists do not compete for the orthosteric pocket and do not have the highest affinity for it.',
 gist:'A second place on the receptor; changes another drug’s affinity or efficacy; both bound.',
 scene:'Propranolol and epinephrine fight over one pocket on the receptor, while drug X binds the same receptor somewhere else and is bound at the same time as either of them, making the pocket work better or worse.',
 confuse:['orthosteric','indirect-antagonist','allosteric-agonist'],
 fig:'classes',
 quote:'These drugs do not bind or compete for the orthostatic binding pocket. They bind someplace else on the receptor.',
 cite:'Pharmacodynamics-Day_2_2026s copy.pdf slides ~19–~20, ~39, ~44; Pharmacodynamics-Day-1-2026s.pdf slide ~29; transcript 9/22; transcript 9/23',
 src:'both'},


{id:'two-state', term:'Two-state model', lecture:'L03', group:'Drug–receptor binding',
 def:'Receptors exist in two states, inactive/resting (R) and active (R*), and move between them on their own; L is the equilibrium constant between [R] and [R*]. Drugs have affinity for R and/or R* (Kd and Kd*) and shift the balance: toward R* is positive efficacy, toward R is negative efficacy.',
 hook:'“This is gonna be home for us.” It explains inverse agonists, which occupancy theory could not. Most receptors sit in the inactive state to save energy.',
 gist:'Receptors flip between inactive R and active R*; drugs shift the balance.',
 scene:'A receptor sits inactive most of the time to save energy and flips to active on its own; a drug with affinity for the active form holds it there, a drug preferring the inactive form holds it back.',
 confuse:['intrinsic-activity'],
 fig:'two-state',
 quote:'So this two-state model shows that we have receptor two confirmations, active and inactive, and that drugs can shift them once bound to the receptor from one confirmation to the other.',
 cite:'Pharmacodynamics-Day_3_2026s.pdf slide ~31; Pharmacodynamics-Day-1-2026s.pdf slide ~28; transcript 9/22; transcript 9/23',
 src:'both'},

/* ---------------- Drug classes ---------------- */
{id:'full-agonist', term:'Full agonist', lecture:'L03', group:'Drug classes',
 def:'Binds and stabilizes the receptor in the active state (R*): highest affinity for active-state receptors, positive (high) efficacy, and can reach 100% of the system’s maximal response. Examples: norepinephrine, epinephrine, acetylcholine.',
 hook:'Same affinity preference as a partial agonist; the difference is efficacy (100% vs 1–99%). “I do not know of any agonist that is irreversible.”',
 gist:'Prefers the active receptor, positive efficacy, reaches 100% of the system’s maximal response.',
 scene:'Norepinephrine on β1 drives the heart rate all the way to 100% of what the heart can produce, and epinephrine on the same receptor does the same; both reversible.',
 confuse:['partial-agonist','inverse-agonist'],
 fig:'classes',
 quote:'Let’s think about that we can dim, so we have one that can kind of go full bright or just halfway bright, a full agonist or a partial.',
 cite:'Pharmacodynamics-Day_3_2026s.pdf slides ~33–~41; Pharmacodynamics-Day_2_2026s copy.pdf slides ~32–~34; transcript 9/23; transcript 9/24',
 src:'both'},

{id:'partial-agonist', term:'Partial agonist', lecture:'L03', group:'Drug classes',
 def:'Positive efficacy but lower than a full agonist (1–99%): it converts inactive receptors to active but cannot reach 100% of the system’s max response (Emax less than 100%) and cannot bring the response all the way to 100% or 0%. Examples: albuterol (β2), varenicline (Nn), pindolol (β1, β2), aripiprazole (D2).',
 hook:'Dual nature: it may act as an agonist or an antagonist depending on the physiological state (varenicline during smoking vs withdrawal). A partial agonist can still be the most potent drug on a graph.',
 gist:'Positive efficacy but below 100%; may act as agonist or antagonist by state.',
 scene:'Varenicline at the nicotinic receptor activates it enough to stop cravings in withdrawal but, in a smoker, competes with nicotine and brings the response down; pindolol raises a very low heart rate and lowers a high one.',
 confuse:['full-agonist','neutral-antagonist','inverse-agonist'],
 fig:'classes',
 quote:'So sometimes we may use a partial agonist over a full agonist because we don’t need to get the max effect. We just need to get enough of it.',
 cite:'Pharmacodynamics-Day_3_2026s.pdf slides ~50–~65; Pharmacodynamics-Day_2_2026s copy.pdf slides ~32–~34; transcript 9/23; transcript 9/24',
 src:'both'},

{id:'inverse-agonist', term:'Inverse agonist', lecture:'L02', group:'Drug classes',
 def:'Has the highest affinity for inactive receptors and negative efficacy: if it binds an active receptor it inhibits it, shifting receptors to the inactive state. Example: the antihistamine loratadine at H1.',
 hook:'Petri dish with 50% of receptors naturally active: an inverse agonist brings cAMP production to zero; a competitive (neutral) antagonist leaves it at 50%.',
 gist:'Prefers the inactive receptor; negative efficacy, takes the baseline down to zero.',
 scene:'In a petri dish where half the H1 receptors are active by themselves, loratadine brings cyclic AMP production to zero; with histamine present, histamine must be raised to compete.',
 confuse:['neutral-antagonist','partial-agonist'],
 fig:'classes',
 quote:'These drugs love to bind to receptors that are inactive and keep them inactive. But they have what is called negative efficacy, which means is if they bind to a receptor that is already active, producing a signal, once they are bound, they’re going to shut them off.',
 cite:'Pharmacodynamics-Day_2_2026s copy.pdf slides ~35–~36; Pharmacodynamics-Day-1-2026s.pdf slide ~28; transcript 9/22; transcript 9/23',
 src:'both'},

{id:'neutral-antagonist', term:'Antagonist (neutral, reversible)', lecture:'L02', group:'Drug classes',
 def:'The two-state description of the competitive antagonist: no efficacy (ε = zero) and equal affinity for receptors in the active and inactive state, so it occupies the receptor and keeps agonists from binding but does not change the balance of receptor states. Examples: prazosin (α1), metoprolol (β1).',
 hook:'“Just a straight line”: an antagonist does not change the balance of receptors; an inverse agonist wants to keep everybody inactive. Intrinsic activity of an antagonist is zero.',
 gist:'Zero efficacy, equal affinity for both receptor states; occupies, changes no balance.',
 scene:'In a petri dish with half the receptors active, prazosin or metoprolol is added and the cyclic AMP stays at 50%: a straight line, the receptors keep whatever state they had.',
 confuse:['inverse-agonist','partial-agonist'],
 fig:'classes',
 quote:'Antagonists, they’re neutral. Like they don’t care if the receptor is active or inactive, they have equal affinity for both receptor states.',
 cite:'Pharmacodynamics-Day_2_2026s copy.pdf slides ~37–~38; transcript 9/23; transcript 9/24',
 src:'both'},

{id:'competitive-antagonist', term:'Competitive (reversible) antagonist', lecture:'L02', group:'Drug classes',
 def:'An antagonist held by ionic, hydrogen or van der Waals bonds: it competes with the agonist for the orthosteric pocket, binds and comes off, and can be outcompeted by more agonist (the agonist still reaches its Emax). Example: prazosin at α1.',
 hook:'Every drug on the Exam 1 drug list is reversible and competitive except phenoxybenzamine. On the curve: shift to the right, symmetrical shifts toward infinity, no change to the baseline, no change to the Emax, because they bind and they come off.',
 gist:'Weak bonds, same pocket, binds and comes off; more agonist still reaches the maximum.',
 scene:'Prazosin sits in the α1 pocket but comes off, so when norepinephrine is raised tenfold it wins back the receptors; the curve moves right in equal steps and still reaches its top.',
 confuse:['irreversible-antagonist','indirect-antagonist'],
 fig:'classes',
 quote:'when we think about uh ionic bonds, hydrogen bonds, [van der Waals] bonds, those are going to be reversible, surmountable, competitive. Different words ... they’re gonna bind and they’re gonna come off.',
 cite:'Pharmacodynamics-Day_2_2026s copy.pdf slides ~15–~16, ~18, ~37; transcript 9/23',
 src:'both'},

{id:'irreversible-antagonist', term:'Irreversible (non-competitive) antagonist', lecture:'L02', group:'Drug classes',
 def:'An antagonist that binds by a covalent bond, so once bound it does not come off at body temperature and the agonist cannot outcompete it. It has the highest affinity (smallest Kd). Example: phenoxybenzamine (α1 and α2).',
 hook:'Once phenoxybenzamine is bound the receptor has to be internalized and recycled and the body must make new ones. Poll: phenoxybenzamine has higher affinity than prazosin. On the curve: shift right, no change to the baseline, Emax down, all the way to 0 (can abolish the DRC); spare receptors delay the drop.',
 gist:'Covalent, never comes off; agonist cannot outcompete it, the maximum falls toward zero.',
 scene:'Phenoxybenzamine forms a covalent bond at α1 and does not come off; the receptor must be internalized and replaced, and with enough of it norepinephrine can no longer reach its top response.',
 confuse:['competitive-antagonist','covalent-bond','inverse-agonist'],
 fig:'classes',
 quote:'This is an irreversible antagonist, non-competitive, insurmountable. So what kind of bo[n]ds does it form? Covalent.',
 cite:'Pharmacodynamics-Day_2_2026s copy.pdf slides ~15, ~18, ~37–~38; transcript 9/23; transcript 9/24',
 src:'both'},

{id:'indirect-antagonist', fig:'ind-ssri', term:'Indirect antagonist', lecture:'L02', group:'Drug classes',
 def:'A drug that inhibits the generation of a biological response by binding to components upstream or downstream from the receptor rather than the receptor itself; it can be reversible or irreversible. Examples: caffeine blocking PDE, a cancer drug blocking RAS.',
 hook:'It can raise the response (caffeine on PDE raises cAMP; a norepinephrine transporter blocker makes norepinephrine appear more potent) or lower it (RAS blocker stops cell growth). It is not allosteric: it never touches the receptor.',
 gist:'Binds upstream or downstream of the receptor, never the receptor; raises or lowers response.',
 scene:'Caffeine blocks phosphodiesterase (PDE) so cyclic AMP piles up and the agonist looks more potent; a cancer drug blocks RAS and the cells stop growing. Neither touches the receptor.',
 confuse:['allosteric','competitive-antagonist'],
 quote:'So, remember that indirect antagonists can work downstream from the receptor, but also upstream from the receptor, OK?',
 cite:'Pharmacodynamics-Day_2_2026s copy.pdf slides ~40–~41; Pharmacodynamics-Day_4_-_5_2026s_pptx Part 2.pdf pages 4–13; transcript 9/23; transcript 9/24; transcript 9/29',
 src:'both'},

{id:'allosteric-agonist', fig:'classes', term:'Allosteric agonist (PAM)', lecture:'L02', group:'Drug classes',
 def:'Binds at a different site on the receptor and increases the affinity and/or efficacy of another drug for the receptor (positive allosteric modulator, PAM). Diazepam and other benzodiazepines increase the affinity and/or efficacy of GABA at the GABA-A chloride channel.',
 hook:'Diazepam is the allosteric agonist on the drug list “that you have to know for your exam.” A benzodiazepine plus alcohol puts two allosteric agonists on one receptor.',
 gist:'Binds a second site and raises another drug’s affinity and/or efficacy, like diazepam.',
 scene:'Diazepam binds the GABA-A chloride channel away from where GABA (gamma-aminobutyric acid) binds, and GABA then opens the channel more readily; add alcohol and two such drugs are on the one receptor.',
 confuse:['allosteric-antagonist','full-agonist'],
 fig:'classes',
 quote:'Benzos increase the affinity And/or efficacy of GABA For its receptor',
 cite:'Pharmacodynamics-Day_2_2026s copy.pdf slides ~21–~24, ~42; transcript 9/23',
 src:'both'},

{id:'allosteric-antagonist', fig:'classes', term:'Allosteric antagonist (NAM)', lecture:'L02', group:'Drug classes',
 def:'Binds at a different site on the receptor and decreases the affinity and/or efficacy of another drug for the receptor.',
 hook:'Literature name: negative allosteric modulator (NAM); the allosteric agonist is the PAM. It does not compete for the orthosteric pocket; a competitive antagonist does. “As far as I know, all allosteric agonists and antagonists are reversible.”',
 gist:'Binds a second site and decreases another drug’s affinity and/or efficacy; reversible.',
 scene:'A drug binds the receptor outside the agonist’s pocket, so both are bound at once, and the agonist now needs more dose or cannot reach its top; the shifts are unequal and stop after enough doses.',
 confuse:['allosteric-agonist','competitive-antagonist','indirect-antagonist'],
 fig:'classes',
 quote:'Allosteric Antagonist: Binds at a different binding site in the receptor; Can decrease the affinity and/or efficacy of another drug for the receptor',
 cite:'Pharmacodynamics-Day_2_2026s copy.pdf slide ~43; transcript 9/23',
 src:'both'},

/* ---------------- Dose–response curves ---------------- */
{id:'drc', term:'Dose–response curve (DRC / CRC)', lecture:'L03', group:'Dose–response curves',
 def:'A graph relating drug dose or concentration on the x-axis (independent variable, log units, sigmoid curve) to the intensity of effect on the y-axis (dependent variable, normalized as % of maximum response). It is the model used to predict and compare drugs and determine potency.',
 hook:'DRC: increasing individual doses in vivo (ADME, apparent potency). CRC: increasing concentration in vitro (molar, pharmacological potency). Affinity is on the x-axis, efficacy on the y-axis, potency a combination of the two.',
 gist:'Log dose on the x-axis, percent of maximal effect on the y-axis; sigmoid.',
 scene:'Increasing doses of norepinephrine are given and the heart rate at each is plotted as percent of the maximum against log dose; the points trace an S shape from which the ED50 is read.',
 confuse:['binding-curve','graded-response'],
 fig:'drc-basic',
 quote:'So my dose is going to be on the bottom, on the X axis. My response is gonna be on the Y axis, which is on the up or down, OK?',
 cite:'Pharmacodynamics-Day_3_2026s.pdf slides ~8–~10, ~16–~18; Pharmacodynamics-Day_2_2026s copy.pdf slide ~56; transcript 9/24',
 src:'both'},

{id:'graded-response', term:'Graded response', lecture:'L03', group:'Dose–response curves',
 def:'A response measured in a single biological unit on a continuous scale that increases by degrees as the dose is raised over a specific range (e.g., 10-fold steps); a graded DRC/CRC relates the dose to the intensity of the effect.',
 hook:'The y-axis is normalized (% of maximum response or response per tissue weight) to eliminate biological variability between individuals: “now I can compare apples with apples.”',
 gist:'Measured in one biological unit on a continuous scale, rising by degrees with dose.',
 scene:'One strip of muscle in a bath is given nicotine in 10-fold steps and the degree of contraction is measured at each step: a little, then more, then more.',
 confuse:['drc','threshold'],
 quote:'Graded response by multiple increases of drug doses over a specific range',
 cite:'Pharmacodynamics-Day_3_2026s.pdf slides ~10, ~16, ~18; transcript 9/24',
 src:'slide'},

{id:'threshold', term:'Threshold', lecture:'L03', group:'Dose–response curves',
 def:'The concentration of the drug below which there is no response: the dose right before something happens. It must be known, with Emax, to calculate the EC50/ED50.',
 hook:'Threshold is where the curve starts; EC50 is the halfway point; Emax is the ceiling.',
 gist:'The dose right before something happens; below it, no effect at all.',
 scene:'A tissue is given 10^-9 molar and nothing happens; at 10^-8 the first effect appears. The dose right before the effect appeared is where the curve starts.',
 confuse:['ec50','emax','slope'],
 fig:'drc-basic',
 quote:'Remember that the threshold is the dose right before something happens, right? So I know that at any dose below this, no effect.',
 cite:'Pharmacodynamics-Day_3_2026s.pdf slides ~20–~21; transcript 9/24',
 src:'both'},

{id:'emax', term:'Emax (maximal response, ceiling)', lecture:'L03', group:'Dose–response curves',
 def:'The plateau of the dose–response curve (ceiling of effect), reached either because all receptors are occupied or because the physiological system has maxed out. Its height reflects efficacy.',
 hook:'Giving more drug past the ceiling does no more good. Curves with equal Emax differ by affinity; when EC50 is equal, greater efficacy makes the drug more potent (Relative Efficacy slide).',
 gist:'The plateau: all receptors occupied or the physiological system maxed out.',
 scene:'Adding more norepinephrine past a certain dose does not raise the heart rate any further, either because every receptor is occupied or because the heart cannot beat faster.',
 confuse:['ec50','efficacy','threshold'],
 fig:'drc-basic',
 quote:'What are the two reasons why we have reached the Emacs and we can’t keep going up? All the receptors are occupied or I max out the physiological system, right?',
 cite:'Pharmacodynamics-Day_3_2026s.pdf slides ~11–~14, ~20–~21, ~27; transcript 9/24',
 src:'both'},

{id:'slope', term:'Slope', lecture:'L03', group:'Dose–response curves',
 def:'The linear mid-section of the sigmoid curve, where the greatest change in effect comes from the smallest change in dose. A steep slope means a narrow dose range from no effect to maximum; a shallow slope means a wider range of doses before Emax.',
 hook:'Which is better “depends”: the steep curve goes from no effect to max all at once; the shallow one gives a greater range of doses before a toxic effect.',
 gist:'The linear mid-section; greatest change in effect from the smallest change in dose.',
 scene:'Two drugs: one goes from no effect to its top within a narrow range of doses, the other needs a much wider range of doses before it tops out and gives more room before toxicity.',
 confuse:['threshold','emax','potency'],
 quote:'In that slope in that area of the curve, this is when I’m going to get the most bang for my buck. This is I’m going to get the greatest change in the response with the smallest change in the dose.',
 cite:'Pharmacodynamics-Day_3_2026s.pdf slides ~20–~21; transcript 9/24',
 src:'both'},

{id:'ec50', term:'EC50 / ED50', lecture:'L03', group:'Dose–response curves',
 def:'The effective concentration (in vitro) or effective dose (in vivo) that produces 50% of a drug’s maximal response: the indicator of potency. The smaller it is, the greater the potency (inversely proportional).',
 hook:'Kd is the concentration binding 50% of receptors (affinity, no effect); EC50 is 50% of the response (potency). Both are read on the x-axis. “Philosophically identical”: one is a dose, the other a concentration.',
 gist:'Concentration (or dose) producing 50% of the maximal response; smaller means more potent.',
 scene:'From the heart-rate curve the point halfway between no effect and the top is dropped to the x-axis, and the concentration read there is the one used to compare drugs; in the whole animal it is a dose instead.',
 confuse:['kd','emax','potency'],
 fig:'drc-basic',
 quote:'So, the take-home message that you can’t forget is that the smallest the ED50 is or the [EC]50, the greater the potency is gonna be. They’re inverse proportional.',
 cite:'Pharmacodynamics-Day_2_2026s copy.pdf slides ~57–~58; Pharmacodynamics-Day_3_2026s.pdf slides ~20–~22, ~29; transcript 9/24',
 src:'both'},

{id:'potency', term:'Potency (pharmacological)', lecture:'L03', group:'Dose–response curves',
 def:'How much drug is needed for a given response, measured by the EC50 or ED50 and read on the x-axis (further left = more potent). It is a combination of affinity, efficacy and the tissue (number of receptors).',
 hook:'Potency ≠ efficacy: the most potent drug (smallest EC50) can be a partial agonist; the most efficacious has the highest Emax. “Affinity is gonna be on the bottom, efficacy is gonna be on the Y axis, and potency is gonna be a combination of the two.”',
 gist:'How much drug is needed; a combination of affinity, efficacy and the tissue.',
 scene:'Of five curves on one plot, drug A sits furthest left, needing the smallest dose for an equivalent effect, even though drug B reaches a higher top; put the same drug A in a tissue with more receptors and it needs even less.',
 confuse:['efficacy','affinity','apparent-potency'],
 fig:'potency',
 quote:'The take home message over here is that potency is not only going to be defined by the efficacy of the affinity, but also the tissue that is going to be bound to.',
 cite:'Pharmacodynamics-Day_3_2026s.pdf slides ~7, ~22, ~27–~29; Pharmacodynamics-Day_2_2026s copy.pdf slides ~52–~54; Pharmacodynamics-Day-1-2026s.pdf slides ~21–~22, ~27; transcript 9/22; transcript 9/23; transcript 9/24',
 src:'both'},

{id:'apparent-potency', term:'Apparent potency', lecture:'L01', group:'Dose–response curves',
 def:'The potency seen in vivo, where pharmacokinetics (age, absorption, distribution, elimination, drug–drug interactions) determines how much drug reaches the site of action; it is not the total concentration of the drug that acts. A DRC built in vivo (ED50) shows it.',
 hook:'Route of administration and first-pass metabolism change apparent potency (IV has 100% bioavailability); they do not change the drug’s affinity or efficacy, which set pharmacological potency.',
 gist:'In vivo potency: affinity and efficacy unchanged, but altered by absorption, elimination, age.',
 scene:'The same drug given by mouth and by vein: by vein 100% reaches the blood, by mouth the liver removes part on the first pass, so the oral dose seems weaker though the drug’s affinity and efficacy are identical.',
 confuse:['potency','pharmacokinetics'],
 quote:'So this is going to give us our apparent potency. Why is apparent? ... It’s only appearing because it’s not the total concentration of the drug.',
 cite:'Pharmacodynamics-Day-1-2026s.pdf slides ~23, ~27; Pharmacodynamics-Day_3_2026s.pdf slide ~8; transcript 9/22',
 src:'both'},

{id:'relative-potency', term:'Relative potency', lecture:'L03', group:'Dose–response curves',
 def:'The ratio of two drugs’ ED50 (or EC50) values, ED50B / ED50A. A drug that needs 1000 times less drug to produce an equivalent response is 1000X more potent.',
 hook:'Compare potency at equivalent effects (e.g., 50%), not at 100%, because a partial agonist never reaches 100%. “Math is gonna be minimal.”',
 gist:'The ratio of two drugs’ ED50 values, compared at equivalent effects.',
 scene:'Drug A needs 1000 times less than drug B to produce an equivalent effect, so dividing B’s half-maximal dose by A’s gives 1000, and the comparison is made at 50%, never at 100%.',
 confuse:['potency','ec50'],
 quote:'We can say that a drug A is 1000 times more potent than drug B because it requires 1000 times less drug to produce equivalent responses.',
 cite:'Pharmacodynamics-Day_3_2026s.pdf slide ~23; transcript 9/24',
 src:'both'},

/* ---------------- Receptors and signaling ---------------- */
{id:'signal-transduction', term:'Signal transduction', lecture:'L02', group:'Receptors and signaling',
 def:'The sequence signal (hormone, growth factor, neurotransmitter, agonist drug) → receptor → transducer → effector (signal amplifier) → second messenger → physiological response: the signaling that occurs prior to the response. Drugs can change the activity of these proteins, and many of them can be drug targets.',
 hook:'Exam ask: identify what is a signal, a receptor, a transducer, an effector (“factor system”) and a second messenger in a pathway like epinephrine → β1 → Gαs → AC → cAMP.',
 gist:'The whole sequence: signal, receptor, transducer, effector, second messenger, physiological response.',
 scene:'Epinephrine arrives at β1, the Gαs subunit translates the change, adenylate cyclase amplifies it into cyclic AMP, and the heart rate rises: five steps in a row from arrival to effect.',
 confuse:['transducer','effector','second-messenger'],
 fig:'gpcr',
 quote:'Signal Transduction: Signal ... Receptor ... Transducer ... Effector (Signal Amplifier) ... 2nd Messenger ... Physiological Response',
 cite:'Pharmacodynamics-Day_2_2026s copy.pdf slides ~25–~28; transcript 9/23',
 src:'both'},

{id:'transducer', term:'Transducer', lecture:'L02', group:'Receptors and signaling',
 def:'The component that translates, integrates and coordinates the signal from the activated receptor, e.g., the G protein.',
 hook:'“Fancy name for translation.” Transducer = G protein; effector = the enzyme it activates (AC, PLC); second messenger = the small molecule the effector makes (cAMP, IP3).',
 gist:'Translates the activated receptor’s change to the effector; the G protein.',
 scene:'Norepinephrine changes the shape of β1, and the Gαs protein understands that change and passes it along to adenylate cyclase; it neither receives the hormone nor makes cyclic AMP.',
 confuse:['effector','second-messenger'],
 fig:'gpcr-steps',
 quote:'Our G protein, for example, can understand that change in the receptor. And by understanding and translating that change, it’s going to be called the transducer.',
 cite:'Pharmacodynamics-Day_2_2026s copy.pdf slides ~26–~28; transcript 9/23',
 src:'both'},

{id:'effector', term:'Effector (signal amplifier)', lecture:'L02', group:'Receptors and signaling',
 def:'An enzyme, ion channel or transport protein that creates, moves or degrades a small molecule or ions, e.g., adenylate cyclase (AC), phospholipase C (PLC). It amplifies the signal (his “factor system”) and is frequently not the ultimate physiological target.',
 hook:'Poll trap: “phospholipase C is an example of a second messenger” — no, PLC is the effector (his “factor system”); IP3 is its second messenger.',
 gist:'The enzyme or channel making or degrading the second messenger; adenylate cyclase, phospholipase C.',
 scene:'Once Gαq reaches it, phospholipase C converts PIP2 (phosphatidylinositol bisphosphate) into IP3 (inositol trisphosphate): it is the enzyme that makes the small molecule, not the small molecule itself.',
 confuse:['second-messenger','transducer'],
 fig:'gpcr-steps',
 quote:'Frequently, the proximal cellular effector protein is not the ultimate physiological target but rather is an enzyme, ion channel, or transport protein that creates, moves, or degrades a small molecule or ions',
 cite:'Pharmacodynamics-Day_2_2026s copy.pdf slides ~26–~28; transcript 9/23',
 src:'both'},

{id:'second-messenger', term:'Second messenger', lecture:'L02', group:'Receptors and signaling',
 def:'Small molecules created, degraded or moved by an enzyme, ion channel or transport protein (the effector); they diffuse near their site of synthesis and convey information to a variety of targets. Slide examples: cAMP, PKA, PKC, IP3, Ca++.',
 hook:'“If there is cAMP and PKA, then select all ... you shouldn’t be picking the receptor or the AC or the calcium channel.” For the Gq pathway the two to know are IP3 and Ca++.',
 gist:'The small molecule the effector makes: cyclic AMP, calcium; it diffuses to its targets.',
 scene:'Adenylate cyclase turns ATP (adenosine triphosphate) into cyclic AMP, which spreads near where it was made and activates protein kinase A, which activates the next step, until the heart beats faster.',
 confuse:['effector','transducer'],
 fig:'gpcr-steps',
 quote:'The production of the second messenger, which then is going to activate another 2nd messenger and then another 2nd messenger, just like a domino cascade until I get the physiological response that I want.',
 cite:'Pharmacodynamics-Day_2_2026s copy.pdf slide ~29; Pharmacodynamics-Day-1-2026s.pdf slides ~52–~53; transcript 9/23',
 src:'both'},

{id:'g-protein', term:'G protein (heterotrimeric)', lecture:'L01', group:'Receptors and signaling',
 def:'Heterotrimeric guanine nucleotide binding protein (α, β, γ subunits) coupled to 7-transmembrane receptors, defined and regulated by the α subunit. Cycle: agonist binds, the receptor activates, GDP comes off and GTP comes on, α dissociates and activates the effector (AC or PLC). Reverse: the extra phosphate is removed (GTP → GDP), α reassociates with β/γ and the receptor resets; PDE breaks down the cAMP.',
 hook:'The G protein is the transducer. Poll trap: G proteins are defined by the α subunit, not the β subunit.',
 gist:'Three subunits; diphosphate off, triphosphate on, α leaves β and γ, activates the effector.',
 scene:'Norepinephrine binds β1 in the heart; the α subunit lets its diphosphate off, takes a triphosphate on, breaks away from β and γ and switches on adenylate cyclase. Then the extra phosphate is removed and α rejoins β and γ.',
 confuse:['gpcr','g-alpha'],
 fig:'gpcr-steps',
 quote:'The GDP, the diphosphate, has to come off, and the G[T]P, as in taxes, the triphosphate has to come in. The removal of the GDP and replacement with the G[T]P is what triggers them to separate from each other.',
 cite:'Pharmacodynamics-Day-1-2026s.pdf slides ~49–~55; Pharmacodynamics-Day_2_2026s copy.pdf slide ~3; transcript 9/23',
 src:'both'},

{id:'g-alpha', term:'Gαs, Gαi and Gαq', lecture:'L02', group:'Receptors and signaling',
 def:'The three α subunit types to know: one (stimulation) activates adenylate cyclase and increases cAMP (β1 in the heart, ↑HR); one (inhibition) inhibits adenylate cyclase and decreases cAMP (M2 in the heart, ↓HR; α2 in the CNS); one activates phospholipase C, which converts PIP2 to IP3 and releases Ca++ from the ER (α1 in smooth muscle).',
 hook:'His cue: adenylate cyclase goes with cyclic AMP; αq goes with phospholipase C and IP3. Gαi is the trap: same effector as Gαs, opposite direction.',
 gist:'Three α types: s raises cyclic AMP, i lowers it, q releases calcium.',
 scene:'At β1 in the heart the α subunit turns adenylate cyclase on and cyclic AMP rises; at M2 a different α subunit turns the same enzyme down; at α1 in smooth muscle a third α subunit turns on phospholipase C and calcium is released.',
 confuse:['g-protein','effector','cross-talk'],
 fig:'gpcr',
 quote:'We know that the alpha S always is going to be associated with the AC and always is going to increase the camp. The alphai, which is the opposite, also is going to be associated with the AC, but in this case it’s going to suppress the camp. And then the alpha Q is going to increase IP3 and calcium.',
 cite:'Pharmacodynamics-Day_2_2026s copy.pdf slides ~3, ~30; Pharmacodynamics-Day-1-2026s.pdf slides ~50–~55; transcript 9/23',
 src:'both'},

{id:'gpcr', term:'G protein–coupled receptor (GPCR, 7-TM)', lecture:'L01', group:'Receptors and signaling',
 def:'7-transmembrane proteins that cross the membrane seven times and couple to a heterotrimeric G protein. The largest single class of pharmacological receptors. Examples: α and β adrenergic, 5HT (serotonin), histamine, muscarinic receptors.',
 hook:'Four receptor classes: ion channels (L-type Ca++, GABA), 7-TM GPCRs, 1-TM (tyrosine kinases), intracellular/nuclear (steroid hormones). “If you know how they work, you’ve got 60% of the drugs in your pocket.”',
 gist:'Crosses the membrane seven times, coupled to a G protein; 60% of drugs.',
 scene:'A protein that crosses the membrane seven times; epinephrine binds on the outside and an α subunit inside passes the activation on to adenylate cyclase. More than 60% of medicines on the market act on this class.',
 confuse:['rtk','ion-channel','g-protein'],
 fig:'gpcr-steps',
 quote:'About 60 or more% of all drugs in the market target one of kind of these receptors. So if you know how they work, you’ve got 60% of the drugs in your pocket.',
 cite:'Pharmacodynamics-Day-1-2026s.pdf slides ~35–~36, ~49; transcript 9/22',
 src:'both'},

{id:'ion-channel', term:'Ion channel (ligand-gated)', lecture:'L01', group:'Receptors and signaling',
 def:'Transmembrane proteins that convey their signal by altering membrane potential or ionic composition (Na+, K+, Ca2+, Cl−); classified by the ions they conduct, their architecture and what opens them. Ligand-gated channels are usually closed with the binding pocket located in the channel (acetylcholine at the nicotinic receptor; GABA at GABA-A).',
 hook:'Passive: always open (resting potential, funny channel). Voltage-gated: open only at certain membrane potentials (Ca++ channels open as the membrane becomes more positive). Stretch: pressure sensitive (baroreceptors). Pumps: move ions against the gradient (Na+/K+ ATPase).',
 gist:'A membrane pore usually closed; the binding pocket is in the channel itself.',
 scene:'Acetylcholine binds two α subunits of the nicotinic protein; the pore opens, sodium flows in, and the membrane becomes less negative.',
 confuse:['gpcr','rtk'],
 quote:'You have a drug, a neurotransmitter, a hormone that is binding to a specific receptor. Once it’s bound, you can open it and allow things to move through it.',
 cite:'Pharmacodynamics-Day-1-2026s.pdf slides ~35–~36, ~39–~48; transcript 9/23',
 src:'both'},

{id:'rtk', term:'Receptor tyrosine kinase (RTK, 1-TM)', lecture:'L02', group:'Receptors and signaling',
 def:'A 1-transmembrane receptor linked to an intracellular enzyme: an extracellular binding domain outside and intrinsic enzymatic (catalytic) activity inside. Ligand binding to the inactive monomer induces dimerization, cross-phosphorylation of the kinase domains and docking sites for signaling complexes; a tyrosine phosphatase resets it. Receptors for insulin and growth factors (cell survival, proliferation, differentiation).',
 hook:'Downstream: Grb2 → GEF → RAS → RAF → MEK → ERK → gene transcription; 20–25% of cancers contain a RAS mutation, so a RAS blocker is an indirect antagonist that stops cell growth.',
 gist:'Crosses the membrane once; binding outside, enzyme activity inside; insulin, growth factors.',
 scene:'Insulin binds the outer part of a protein that crosses the membrane once; two of them pair up, phosphorylate each other inside the cell, and the cascade runs through RAS, RAF, MEK and ERK to gene transcription.',
 confuse:['gpcr','nuclear-receptor','ion-channel'],
 quote:'They have this binding pocket on the outside, and they have this enzymatic activity inside of the cell. Typically those are transcription factors like insulin growth factors.',
 cite:'Pharmacodynamics-Day_2_2026s copy.pdf slides ~4–~11; Pharmacodynamics-Day-1-2026s.pdf slides ~35–~36; transcript 9/23',
 src:'both'},

{id:'nuclear-receptor', term:'Nuclear (intracellular) receptor', lecture:'L02', group:'Receptors and signaling',
 def:'Intracellular receptors and transcriptional regulators: a superfamily of 48 receptor proteins that are transcription factor regulators. Ligands (androgens, estrogens, glucocorticoids, thyroid hormone, vitamin D) bind in the cytosol or nucleus and regulate gene expression (protein synthesis or mRNA turnover); co-repressor bound = inactive, co-activator bound = active.',
 hook:'Aldosterone at the mineralocorticoid receptor codes mRNA for more pumps and channels in the principal cell: sodium saving, potassium wasting. Exam ask: “what is the function of a nuclear receptor? How do they work”.',
 gist:'Inside the cell; steroid binds, and gene expression and messenger RNA production change.',
 scene:'Aldosterone enters the principal cell and binds a protein in the cytosol or nucleus; the genes are read differently and more messenger RNA for pumps and channels is made, so sodium is saved and potassium wasted.',
 confuse:['rtk','gpcr'],
 quote:'Those are glucocor[tico]steroids. They are nuclear receptors. They affect DNA. They affect messenger RNA production.',
 cite:'Pharmacodynamics-Day_2_2026s copy.pdf slides ~12–~14; Pharmacodynamics-Day-1-2026s.pdf slides ~35–~36; transcript 9/23',
 src:'both'},

{id:'cross-talk', fig:'crosstalk', term:'Cross-talk', lecture:'L02', group:'Receptors and signaling',
 def:'Interaction between signal transduction pathways within the same cell that yields a net response. In the heart, M2 (Gαi, ↓cAMP, ↓HR) and β1 (Gαs, ↑cAMP, ↑HR) both act on adenylate cyclase.',
 hook:'Two receptors, two G proteins, one effector (AC): the heart rate is the net of the two.',
 gist:'Two receptors in one cell share an effector; the response is their net.',
 scene:'In one heart cell norepinephrine at β1 raises cyclic AMP while acetylcholine at M2 lowers it; the heart rate that results is the balance of the two.',
 confuse:['g-alpha','second-messenger'],
 quote:'So we have multiple receptors that can be activated at the same time as we talked a little bit about that earlier in our heart, we have two major receptors, the beta 1s, which are sympathetic, and the M2s, muscarinics, which are parasympathetic, right?',
 cite:'Pharmacodynamics-Day_2_2026s copy.pdf slide ~30; transcript 9/23',
 src:'both'},

{id:'baseline', term:'Baseline (point of reference)', lecture:'L04', group:'Dose–response curves',
 def:'The starting point of a dose–response curve: a reflection of the receptor activity in the system before the drug is added. With most receptors inactive (R > R*) the baseline is 0%; with half active it is 50%. Every drug-drug question starts from the agonist’s own curve as the point of reference.',
 hook:'One "greater than" sign on the exam means about 99% of receptors are inactive and the baseline is zero. Full agonist raises it, inverse agonist lowers it to zero, neutral antagonists leave it alone.',
 gist:'Where the curve starts: receptor activity before any drug; 0% if most inactive.',
 scene:'In one cell line nearly all receptors sit inactive, so the agonist’s curve begins at 0%; in another, half the receptors are active on their own and the same agonist’s curve begins at 50%.',
 confuse:['emax','two-state'],
 fig:'two-state',
 quote:'The baseline is just a reflection of the receptor activity that is happening.',
 cite:'Pharmacodynamics-Day_4_-_5_2026s_pptx.pdf slides ~15, ~45–~46; transcript 9/28',
 src:'both'},

{id:'constitutive-activity', term:'Constitutive activity', lecture:'L04', group:'Receptors and signaling',
 def:'Receptor activity that is present by itself, without any drug, hormone or neurotransmitter (a baseline above 0%). Receptors that have it are more sensitive to inverse agonists; it is what an inverse agonist shuts down.',
 hook:'Antihistamines were called antagonists until cell lines with naturally active receptors showed that loratadine and cetirizine bring the activity to zero. Listed receptors: histamine, opioid, cannabinoid, dopamine, bradykinin, adenosine.',
 gist:'Receptors active on their own, no drug present; what an inverse agonist removes.',
 scene:'A cell line’s histamine receptors produce a signal with no histamine in the dish; loratadine or cetirizine brings that signal to zero, which is why they were reclassified from antagonists.',
 confuse:['inverse-agonist','neutral-antagonist'],
 fig:'inverse',
 quote:'Receptors that have constitutive activity are more sensitive to inverse agonists',
 cite:'Pharmacodynamics-Day_4_-_5_2026s_pptx.pdf slide ~23; transcript 9/28',
 src:'both'},

{id:'chemical-antagonist', term:'Chemical antagonist', lecture:'L04', group:'Drug classes',
 def:'A drug that antagonizes by a direct chemical interaction with the agonist (or a toxin), binding the chemical so the body can get rid of it. Example: chelating agents such as dimercaprol for gold, mercury or arsenic poisoning.',
 hook:'No receptor is involved; the antagonist binds the chemical itself. Contrast physiological antagonism (two receptors, opposite effects).',
 gist:'Binds the agonist or toxin itself, no receptor involved; dimercaprol chelates mercury.',
 scene:'A patient poisoned with mercury is given dimercaprol, which binds the metal directly so the body can excrete it; no receptor is involved anywhere.',
 confuse:['physiological-antagonist','competitive-antagonist'],
 quote:'Chemical: Direct chemical interaction between the agonist and antagonist. E.g. Chelating agents, dimercaprol',
 cite:'Pharmacodynamics-Day_4_-_5_2026s_pptx.pdf slide ~35; transcript 9/28',
 src:'both'},

{id:'physiological-antagonist', term:'Physiological antagonist', lecture:'L04', group:'Drug classes',
 def:'Two agonists acting independently of each other at different receptors in the same organ and producing opposing effects. Example of the year: acetylcholine at muscarinic receptors lowers heart rate while epinephrine at β1 raises it.',
 hook:'They are not competing for the same receptor; they are affecting the physiology in opposite directions.',
 gist:'Two agonists at different receptors in one organ, pushing in opposite directions.',
 scene:'Acetylcholine at muscarinic receptors slows the heart while epinephrine at β1 speeds it up; neither drug touches the other’s receptor, yet each undoes the other’s effect.',
 confuse:['chemical-antagonist','competitive-antagonist'],
 quote:'They bind to two different receptors in the same organ and producing opposite effects. They’re not competing for the same receptor, they’re just producing different effects.',
 cite:'Pharmacodynamics-Day_4_-_5_2026s_pptx.pdf slide ~35; transcript 9/28',
 src:'both'},

{id:'surmountable', term:'Surmountable / insurmountable', lecture:'L04', group:'Drug classes',
 def:'Surmountable antagonism: giving more agonist overcomes the antagonist, because the antagonist binds and comes off; the agonist still reaches its full Emax, only at a higher dose (competitive = reversible = surmountable). Insurmountable antagonism: no dose of agonist overcomes it, because the antagonist is bound for good; the Emax falls (irreversible = nonequilibrium-competitive = insurmountable).',
 hook:'When to apply it: ask "can the agonist still reach its maximum if I give enough?" Yes, curve shifted right with the same top = surmountable (metoprolol, prazosin). No, the top comes down = insurmountable (phenoxybenzamine).',
 gist:'Surmountable: more agonist wins back the full Emax. Insurmountable: the Emax is lost.',
 scene:'With prazosin on board, raising norepinephrine enough restores the top response; with phenoxybenzamine on board, no amount of norepinephrine brings it back.',
 confuse:['competitive-antagonist','irreversible-antagonist'],
 fig:'shift-competitive',
 quote:'One is competitive antagonist, also known as reversible antagonists, also known as surmountable antagonists, different names for the same drug. They bind and they come off.',
 cite:'Pharmacodynamics-Day_4_-_5_2026s_pptx.pdf slide ~36; transcript 9/28',
 src:'both'},

{id:'symmetrical-shift', term:'Symmetrical vs asymmetrical shifts', lecture:'L04', group:'Dose–response curves',
 def:'Equal steps between successive curves come from increasing doses of an orthosteric competitor (competitive antagonist, inverse agonist, irreversible antagonist), because a tenfold increase in one drug needs a tenfold increase in the other; unequal steps come from allosteric agonists and antagonists, whose binding at the other site does not depend on the agonist.',
 hook:'Asymmetrical plus saturable is how an allosteric drug is recognized on a figure.',
 gist:'Equal steps between curves mean an orthosteric competitor; unequal steps mean allosteric.',
 scene:'Metoprolol at 1x, 10x and 100x moves the norepinephrine curve right by the same distance each time, because tenfold more blocker needs tenfold more agonist; diazepam’s successive moves are unequal.',
 confuse:['saturability','allosteric'],
 fig:'competitive',
 quote:'if I increase the dose by tenfold, I have to increase the dose of the other by tenfold to outcompete them.',
 cite:'Pharmacodynamics-Day_4_-_5_2026s_pptx.pdf slides ~30–~34, ~38, ~48–~50, ~53–~54; transcript 9/28',
 src:'both'},

{id:'saturability', term:'Saturability (allosteric)', lecture:'L04', group:'Dose–response curves',
 def:'The limit to how far an allosteric drug can shift an agonist’s curve: once all the allosteric sites are occupied, higher doses produce no further shift. Orthosteric competitors, by contrast, keep shifting the curve toward infinity as long as more drug can be added.',
 hook:'An allosteric antagonist cannot bring the response all the way to zero; an irreversible antagonist can.',
 gist:'Once every allosteric site is occupied, more drug produces no further shift.',
 scene:'At 100x, 1000x and 10,000x the second drug the agonist’s curve stops moving; every one of the second drug’s sites on the receptor is already taken, while more prazosin would keep moving it toward infinity.',
 confuse:['symmetrical-shift','irreversible-antagonist'],
 quote:'I can keep giving more and more of my allosteric, and he can’t go more to the left. He has maxed out all that he can do to the system.',
 cite:'Pharmacodynamics-Day_4_-_5_2026s_pptx.pdf slides ~30–~34; transcript 9/28',
 src:'both'},

{id:'spare-receptors', term:'Spare receptors', lecture:'L04', group:'Receptors and signaling',
 def:'Receptors beyond the fraction an agonist needs to occupy to produce its maximal response: agonists do not have to occupy 100% of the receptors to produce the maximal effect. With spare receptors an irreversible antagonist first only shifts the agonist’s curve to the right; the Emax falls once the receptors left are fewer than the agonist needs.',
 hook:'Worked example: agonist needs 10%; blocking 75% or 85% still allows the max response at a higher dose; below 10% available the Emax drops toward zero. Take-home 9/29: the more spare receptors, the more potent the agonist; a tissue with many receptors responds to an irreversible antagonist as if it were competitive at first.',
 gist:'Agonists need only a fraction of receptors for maximal effect; the rest are extra.',
 scene:'A tissue reaches its full response when only 10% of its receptors are occupied; blocking 75% of them irreversibly still allows the maximal response at a higher dose.',
 confuse:['irreversible-antagonist','emax'],
 fig:'spare',
 quote:'Our agonists don’t have to occupy 100% of the receptors to produce a response. They only have to occupy a certain percentage of those receptors to do so.',
 cite:'transcript 9/28; Pharmacodynamics-Day_4_-_5_2026s_pptx.pdf slides ~54, ~56; Pharmacodynamics-Day_4_-_5_2026s_pptx Part 2.pdf pages 1–3; transcript 9/29',
 src:'both'},

{id:'withdrawal-syndrome', term:'Withdrawal syndrome', lecture:'L04', group:'Drug basics',
 def:'The opposite of what the drug produces, appearing when the drug is stopped: if nicotine relaxes, lowers appetite and raises blood pressure, withdrawal brings irritability, overeating and lower blood pressure. A partial agonist such as varenicline activates enough of the inactive receptors to take the cravings away without the full effect of nicotine.',
 hook:'The reason people cannot stop smoking; the reason a partial agonist is used for smoking cessation.',
 gist:'The opposite of what the drug produced, appearing when the drug is stopped.',
 scene:'Nicotine relaxed a smoker, lowered appetite and raised blood pressure; when the cigarettes stop, irritability, overeating and lower blood pressure take their place.',
 confuse:['partial-agonist'],
 fig:'partial',
 quote:'Withdrawal syndrome is the opposite of what the drug produces.',
 cite:'Pharmacodynamics-Day_3_2026s.pdf slides ~64–~65; transcript 9/28',
 src:'transcript'},

{id:'up-regulation', term:'Up-regulation', lecture:'L05', group:'Receptors and signaling',
 def:'An increase in the number of receptors (more spare receptors) that follows chronic reduction of receptor stimulation, typically by an antagonist or inverse agonist; a compensatory mechanism. It increases the potency of a full agonist (shift left) and the potency and/or maximal response of a partial agonist.',
 hook:'Stopping a β-blocker cold turkey leaves many up-regulated receptors unblocked: hypertensive crisis, so taper stepwise. Other examples: chronic denervation, thyroid hormone.',
 gist:'More receptors made after chronic antagonist; a compensatory mechanism, agonist becomes more potent.',
 scene:'After months on a β-blocker the heart has grown many more β receptors; stop the blocker cold turkey and norepinephrine meets all of them at once, a hypertensive crisis, so the dose is tapered stepwise.',
 confuse:['down-regulation','spare-receptors'],
 fig:'regulation',
 quote:'So typically an antagonist will up regulate, an agonist is going to down regulate because our body is going to do the opposite to maintain that homeostasis.',
 cite:'Pharmacodynamics-Day_4_-_5_2026s_pptx Part 2.pdf pages 17–19; transcript 9/29',
 src:'both'},

{id:'down-regulation', term:'Down-regulation / desensitization', lecture:'L05', group:'Receptors and signaling',
 def:'The umbrella for what the cell does after prolonged exposure to an agonist (too much stimulation): rapid desensitization, then a reduction in the total number of receptors. Analogous to an irreversible antagonist: fewer receptors, so the agonist becomes less potent (shift right) and may lose its maximal effect.',
 hook:'Clinical manifestations: tolerance (opioids, Afrin-type nasal decongestants, cocaine) and myasthenia gravis. Shut off a Levophed drip and the pressure tanks.',
 gist:'Fewer receptors after too much agonist; analogous to an irreversible antagonist.',
 scene:'A Levophed (norepinephrine) drip has run for days and the cell has removed many of its receptors; shut the drip off and the blood pressure tanks.',
 confuse:['up-regulation','irreversible-antagonist','tolerance'],
 fig:'regulation',
 quote:'Down-Regulation/Desensitization: Analogous to the effects of irreversible acting antagonists',
 cite:'Pharmacodynamics-Day_4_-_5_2026s_pptx Part 2.pdf pages 20–21, 25–29; transcript 9/29',
 src:'both'},

{id:'rapid-desensitization', term:'Rapid desensitization (GRK / β-arrestin)', lecture:'L05', group:'Receptors and signaling',
 def:'Short-term regulation of a G protein–coupled receptor by association with regulatory proteins: the agonist-bound receptor serves as a substrate for GPCR kinases (GRK), GRK phosphorylates the receptor tail, and β-arrestin binds and stops the receptor from signaling (no more cAMP) until the agonist comes off. Occurs within milliseconds and is reversible.',
 hook:'β-arrestin is the stop plug; long-term regulation (synthesis, degradation, internalization) takes time. Poll trap: short-term regulation does not involve relocation into the cell.',
 gist:'A kinase phosphorylates the agonist-bound receptor, β-arrestin stops it; milliseconds, reversible, stays in membrane.',
 scene:'With the agonist still bound, the receptor’s tail is phosphorylated and a regulatory protein attaches, and the cyclic AMP trace falls flat within milliseconds; once the agonist leaves, the receptor resets. It never left the membrane.',
 confuse:['down-regulation','long-term-down-regulation'],
 fig:'desens-rapid',
 quote:'GRK phosphorylates and allows the binding of β-arrestin',
 cite:'Pharmacodynamics-Day_4_-_5_2026s_pptx Part 2.pdf pages 21–24; transcript 9/29',
 src:'both'},

{id:'long-term-down-regulation', term:'Long-term down-regulation (internalization)', lecture:'L05', group:'Receptors and signaling',
 def:'With continued over-stimulation, β-arrestin facilitates uptake of the receptor into coated pits; the receptor is removed from the surface by endocytosis and then either recycled back or degraded in a lysosome. A receptor that is not in the cell membrane cannot bind anything.',
 hook:'Endocytosis, binding to coated pits, recycling, degradation. Cocaine or opioid use keeps stimulating, so the cell gets rid of receptors and keeps them low.',
 gist:'Receptor taken into the cell by endocytosis, then recycled or degraded in a lysosome.',
 scene:'With cocaine or opioids stimulating the receptors day after day, β-arrestin pulls receptors into coated pits, they are taken inside by endocytosis and sent to a lysosome, and the surface count stays low.',
 confuse:['rapid-desensitization','down-regulation'],
 fig:'desens-long',
 quote:'Endocytosis · Binding to coated pits · Recycling · Degradation',
 cite:'Pharmacodynamics-Day_4_-_5_2026s_pptx Part 2.pdf pages 21, 27; transcript 9/29',
 src:'both'},

{id:'tolerance', fig:'desens-long', term:'Tolerance', lecture:'L05', group:'Drug basics',
 def:'The effects that follow continued exposure to the same concentration of a drug are diminished. A clinical manifestation of receptor down-regulation: opioid analgesics, α-adrenoreceptor agonists used as nasal decongestants.',
 hook:'The Afrin box says 2 to 3 days only; the body lowers the receptor number to counteract the stimulation, so more drug is needed for the same effect.',
 gist:'Continued exposure to the same concentration gives a diminished effect; the clinical manifestation.',
 scene:'A patient uses a nasal decongestant spray every day past the 2 to 3 days the box allows; soon the same dose no longer opens the nose and more is needed.',
 confuse:['down-regulation','withdrawal-syndrome'],
 quote:'Tolerance: The effects that follow continue exposure to the same concentration of drug is diminished',
 cite:'Pharmacodynamics-Day_4_-_5_2026s_pptx Part 2.pdf page 29; transcript 9/29',
 src:'both'},

{id:'reuptake-inhibitor', term:'Reuptake inhibitor (SSRI / SNRI)', lecture:'L05', group:'Drug classes',
 def:'An indirect antagonist that blocks the transporter returning a neurotransmitter to the neuron (fluoxetine at SERT; duloxetine at the serotonin and norepinephrine transporters). More neurotransmitter stays in the synapse, so it appears more potent: its curve shifts left with the same Emax.',
 hook:'Same principle, different target as physostigmine (enzyme blocker). Cocaine blocks norepinephrine reuptake the same way and leads to down-regulation.',
 gist:'Blocks the transporter returning the neurotransmitter; more stays in the synapse, curve shifts left.',
 scene:'Fluoxetine blocks the transporter that carries serotonin back into the neuron, so serotonin stays in the synapse longer; its curve moves left with the same top, since the drug is still serotonin.',
 confuse:['allosteric-agonist'],
 fig:'ind-ssri',
 quote:'making serotonin more potent by taking away its break down',
 cite:'Pharmacodynamics-Day_4_-_5_2026s_pptx Part 2.pdf pages 9–11; transcript 9/29',
 src:'both'},

{id:'acetylcholinesterase-inhibitor', term:'Acetylcholinesterase inhibitor (physostigmine)', lecture:'L05', group:'Drug classes',
 def:'An indirect antagonist that blocks the enzyme on parasympathetic cell membranes that breaks down acetylcholine. Acetylcholine levels rise, more receptors are bound, and acetylcholine appears more potent (shift left). Used in myasthenia gravis.',
 hook:'Any drug ending in -stigmine. Myasthenia gravis: about 90% autoimmune, antibodies target the nicotinic receptors of skeletal muscle (down-regulation), progressive weakness through the day.',
 gist:'Blocks the enzyme breaking down acetylcholine; acetylcholine rises and appears more potent.',
 scene:'In myasthenia gravis, antibodies have removed nicotinic receptors from skeletal muscle; a -stigmine drug stops the enzyme that destroys acetylcholine, more acetylcholine reaches the receptors left, and the weakness eases.',
 confuse:['reuptake-inhibitor'],
 fig:'ind-ache',
 quote:'by blocking the enzyme, I can increase the levels of acetylcholine, the more acetylcholine I have, the more receptors I can bind, and thus make acetylcholine more potent, thus shifting to the left.',
 cite:'Pharmacodynamics-Day_4_-_5_2026s_pptx Part 2.pdf pages 12–13, 29; transcript 9/29',
 src:'both'},

{id:'addition', term:'Addition (drug–drug)', lecture:'L05', group:'Drug basics',
 def:'Two different drugs with the same effect are given together and the result is equal to the sum of the individual effects. Example: trimethoprim and sulfamethoxazole (synthesis of folic acid and inhibition of bacterial growth).',
 hook:'One plus one equals two: two antibiotics each killing 50% of a colony kill 100% together.',
 gist:'Two drugs with the same effect; the result equals the sum of each.',
 scene:'Trimethoprim kills 50% of a bacterial colony and sulfamethoxazole kills 50%; given together they kill 100%, exactly the sum of the two.',
 confuse:['synergism','potentiation'],
 quote:'Result is equal to the sum of the individual effect',
 cite:'Pharmacodynamics-Day_4_-_5_2026s_pptx Part 2.pdf page 30; transcript 9/29',
 src:'both'},

{id:'synergism', term:'Synergism', lecture:'L05', group:'Drug basics',
 def:'Two different drugs with the same effect are given together and the result is an effect greater in magnitude than the sum of each drug alone. Example: penicillin and gentamicin (antipseudomonal activity).',
 hook:'One plus one equals five: penicillin kills 30%, gentamicin 50%, together 100%. Both drugs have an effect by themselves, unlike potentiation.',
 gist:'Two drugs with the same effect; the result is greater than their sum.',
 scene:'Penicillin alone kills 30% of a Pseudomonas colony and gentamicin alone 50%; given together they kill 100%, more than the two numbers combined.',
 confuse:['addition','potentiation'],
 quote:'So they both have an effect and when we put them together, they’re greater than the independently they do together.',
 cite:'Pharmacodynamics-Day_4_-_5_2026s_pptx Part 2.pdf page 30; transcript 9/29',
 src:'both'},

{id:'potentiation', term:'Potentiation', lecture:'L05', group:'Drug basics',
 def:'One drug lacks an effect on its own but increases the effect of another. Example: carbidopa and dopa; carbidopa is an inactive analog that blocks the breakdown of dopa in the gut, so more reaches the brain.',
 hook:'Carbidopa alone does nothing for a Parkinson’s patient; it is classified as an indirect antagonist.',
 gist:'One drug has no effect alone but increases the effect of another.',
 scene:'Carbidopa given by itself does nothing for a Parkinson’s patient, but given with dopa it blocks the breakdown of dopa in the gut and far more dopa reaches the brain.',
 confuse:['synergism','indirect-antagonist'],
 quote:'Here, one is neutral, has no effect by itself, but it can make the other a lot more potent.',
 cite:'Pharmacodynamics-Day_4_-_5_2026s_pptx Part 2.pdf page 31; transcript 9/29',
 src:'both'},

{id:'quantal-response', term:'Quantal response', lecture:'L05', group:'Dose–response curves',
 def:'A binary measurement in a population: any effect or none, alive or dead, a defined response such as a 5% increase in blood pressure. Plotted as number responding vs dose it gives a normal distribution; in cumulative form it gives a sigmoidal curve that allows ligands to be compared in a population.',
 hook:'Contrast the graded response measured on one sample (degree of contraction with nicotine, degree of paralysis by curare). The dogs and epinephrine (7.7–108 ng/kg/min) figure; ED50 ≈ 29 ng/kg/min.',
 gist:'All-or-none in a population: alive or dead; cumulative plot gives a sigmoid.',
 scene:'Dogs each get a dose of epinephrine between 7.7 and 108 ng/kg/min and each is scored only as responding or not; the count responding at each dose forms a normal distribution, and the running total a sigmoid.',
 confuse:['graded-response','ed50-population'],
 quote:'Populations usually studied with “Quantal” response',
 cite:'Pharmacodynamics-Day_4_-_5_2026s_pptx Part 2.pdf pages 32–34; transcript 9/29',
 src:'both'},

{id:'ed50-population', term:'ED50 / LD50 (population)', lecture:'L05', group:'Dose–response curves',
 def:'On a cumulative quantal curve, the dose of the drug that protects (treats) 50% of the population and the dose that kills 50% of the population. The lethal curve lies to the right of the effective curve; their ratio is the therapeutic index.',
 hook:'Acetaminophen headache study: ED50 ≈ 325 mg, the regular-strength tablet; > 4000 mg/day is liver toxicity. LD50 comes from animals or from overdoses after marketing (warfarin).',
 gist:'Doses treating 50% and killing 50% of a population on cumulative quantal curves.',
 scene:'In a headache study, 325 mg of acetaminophen, the regular-strength tablet, relieves half the people; the dose that would kill half comes from animals or from overdoses reported after marketing.',
 confuse:['ec50','therapeutic-index'],
 quote:'Dose of the drug that protects 50% of the population (ED50) ... Dose of the drug that kills 50% of the population (LD50)',
 cite:'Pharmacodynamics-Day_4_-_5_2026s_pptx Part 2.pdf pages 36–40; transcript 9/29',
 src:'both'},

{id:'therapeutic-index', term:'Therapeutic index (TI)', lecture:'L05', group:'Dose–response curves',
 def:'An estimate of a drug’s margin of safety from quantal data: the ratio of the toxic (lethal or sub-lethal) effect to the therapeutic effect, LD50/ED50. A statement of how selective a drug is in producing a desired effect. The larger the ratio, the safer the drug.',
 hook:'Phenobarbital 40/4 = 10, alprazolam 2500; figure 160/10 = 16; hypnosis/death 400/100 = 4. Codeine has a huge TI for cough and a tiny one for pain: it is per effect measured. Distractors invert the ratio.',
 gist:'Lethal dose for 50% over effective dose for 50%; larger is safer.',
 scene:'On the figure the curve for death crosses 50% at 160 mg and the curve for the desired effect at 10 mg; 160 divided by 10 gives 16. For codeine the number is huge for cough and tiny for pain.',
 confuse:['safety-index','therapeutic-window'],
 quote:'The larger the ratio the safer the drug',
 cite:'Pharmacodynamics-Day_4_-_5_2026s_pptx Part 2.pdf pages 35, 39–41; transcript 9/29',
 src:'both'},

{id:'safety-index', term:'Safety index (safety ratio)', lecture:'L05', group:'Dose–response curves',
 def:'The dose that kills 1% of patients divided by the dose that treats 99% (LD1/ED99). For a drug to be safe the ED99 should be less than the LD1; the bigger the ratio, the safer. A large TI (1000) can hide a value of 0.1: 99 of 100 patients sleep and one dies.',
 hook:'Example: ED99 = 10, LD1 = 1 → SI = 1/10 = 0.1, not a safe drug even with TI = 100/0.1 = 1000.',
 gist:'Dose killing 1% divided by dose treating 99%; the tails, not the middles.',
 scene:'A sleeping drug: the dose that puts 99 of 100 patients to sleep is 10, and the dose that kills 1 of 100 is 1; dividing 1 by 10 gives 0.1, so one patient dies before everyone sleeps, though the 50% figures gave 1000.',
 confuse:['therapeutic-index','therapeutic-window'],
 quote:'For a drug to be safe the ED99 should be less than the LD1',
 cite:'Pharmacodynamics-Day_4_-_5_2026s_pptx Part 2.pdf page 42; transcript 9/29',
 src:'both'},

{id:'therapeutic-window', term:'Therapeutic window', lecture:'L05', group:'Dose–response curves',
 def:'The range of steady-state concentrations of drug that provides therapeutic efficacy with minimal toxicity. The clinically acceptable risk of toxicity depends critically on the severity of the disease being treated (headache vs Hodgkin’s lymphoma).',
 hook:'Knowing the TI and the SI gives the window in which it is safe to give the drug.',
 gist:'The range of steady-state concentrations giving efficacy with minimal toxicity; not a ratio.',
 scene:'For a headache, the acceptable band of steady-state concentrations is narrow, since almost no toxicity is tolerated; for Hodgkin’s lymphoma a wider band is accepted because the disease is severe.',
 confuse:['therapeutic-index','safety-index'],
 quote:'Is the range of steady-state concentrations of drug that provides therapeutic efficacy with minimal toxicity',
 cite:'Pharmacodynamics-Day_4_-_5_2026s_pptx Part 2.pdf page 43; transcript 9/29',
 src:'both'},

{id:'side-effect', term:'Side effect (ADR)', lecture:'L05', group:'Drug basics',
 def:'An undesired action of a drug (adverse drug reaction, ADR); a toxic effect is an undesired effect that can be lethal or sub-lethal. Predictable if the pharmacology of the ligand is known: the ligand affects receptor function, receptors change cell function, and the change creates the observable clinical response.',
 hook:'Sildenafil (studied for blood pressure, marketed for the erectile side effect) and minoxidil (blood pressure, then hair loss): which action is the effect depends on what you are treating.',
 gist:'An undesired action of the drug; predictable once the ligand’s receptor pharmacology is known.',
 scene:'Sildenafil was studied to lower blood pressure, and the erection it also caused became the reason it is sold; minoxidil was a blood-pressure drug until the hair it grew became its use.',
 confuse:['therapeutic-index'],
 quote:'Undesired actions of drugs are commonly called side effects (or ADR)',
 cite:'Pharmacodynamics-Day_4_-_5_2026s_pptx Part 2.pdf pages 35, 44; transcript 9/29',
 src:'both'},

/* ================= Exam 2 (Days 7–12, 9/30–10/8) =================
   Lectures L07–L12; course.js maps them to Exam 2, so the Terms tab files these
   under Exam 2 and their generated questions carry exam 2 through the lecture field.
   Groups: 'Autonomic layout', 'Autonomic receptors', 'Cholinergic drugs',
   'Adrenergic drugs', 'Nitric oxide', 'RAAS'. Slide N = PDF page N of the deck
   named in cite; quotes keep the transcript spelling. */

/* ---------------- Autonomic layout ---------------- */
{id:'ans', term:'Autonomic nervous system (ANS)', lecture:'L07', group:'Autonomic layout',
 def:'The involuntary (vegetative) part of the peripheral nervous system: it controls organs, vasculature and smooth muscle throughout the body and is made of the sympathetic and parasympathetic systems (the enteric system is drawn under it too). It supplies every innervated structure except skeletal muscle, its ganglia lie entirely outside the brain and spinal cord, and it shows some spontaneous activity.',
 hook:'The somatic system is the voluntary one: a single myelinated fiber from the spinal cord straight to skeletal muscle, acetylcholine on Nm, no ganglion in between.',
 gist:'Involuntary control of organs, vessels and smooth muscle; two divisions plus enteric.',
 scene:'Heart rate, pupil size and the tone of the gut and bladder change all day without the person choosing any of it, while lifting an arm is a choice.',
 confuse:['predominant-tone','dual-innervation'],
 quote:'Autonomic supply all innervated structures of the Body, except for skeletal muscle (Somatic)',
 cite:'Autonomic Nervous System.pdf slides 10–12; transcript 9/30',
 src:'both'},

{id:'pns', term:'Parasympathetic nervous system (PNS)', lecture:'L07', group:'Autonomic layout',
 def:'The craniosacral division of the autonomic nervous system: it conserves energy and maintains organ function during minimal activity (rest and digest). A long preganglionic fiber reaches a ganglion near or at the target organ, about one to one, and a short postganglionic fiber releases acetylcholine onto muscarinic receptors (M2 heart, M3 almost everywhere else). It is the only innervation of the lungs.',
 hook:'Over-activating it gives DUMBBELSS; blocking it gives the opposite. Lungs are parasympathetic only, one of the few “only” statements that is true.',
 gist:'Rest and digest: long fiber to a ganglion at the organ, acetylcholine on muscarinic.',
 scene:'After a large meal on the couch, the heart rate is slow, the pupils are small, the airways are narrowed and the gut is busy moving and secreting.',
 confuse:['sns','dual-innervation'],
 quote:'It is crucial for the maintenance of organ function on the minimal activity, under the resting situations, OK?',
 cite:'Autonomic Nervous System.pdf slides 21–27; transcript 9/30',
 src:'both'},

{id:'sns', term:'Sympathetic nervous system (SNS)', lecture:'L07', group:'Autonomic layout',
 def:'The thoracolumbar division of the autonomic nervous system: ergotropic (it spends energy), not essential to life but critical during stress (fight or flight). A short preganglionic fiber reaches a ganglion that fans out about one to twenty, and a long postganglionic fiber releases norepinephrine onto α and β receptors. Vasoconstriction of the blood vessels is its resting tone; it is the only innervation of blood vessels and kidneys.',
 hook:'One to many lets every organ change at the same time. Exceptions: the adrenal medulla (acetylcholine on a nicotinic receptor) and the salivary glands (acetylcholine on M3).',
 gist:'Spends energy for fight or flight; short first fiber, one to many, norepinephrine.',
 scene:'A dog starts chasing a jogger: the heart races, the pupils widen, the airways open and blood is sent to the leg muscles, every organ changing at once.',
 confuse:['pns','adrenal-medulla'],
 quote:'You have a short fiber and then a long fiber to the organ. Most of it, the parasympathetic is typically like 1 to 1. ... The sympathetic is one to many. ... One You can control more at once, right?',
 cite:'Autonomic Nervous System.pdf slides 28–35; transcript 10/1',
 src:'both'},

{id:'preganglionic', term:'Preganglionic fiber', lecture:'L07', group:'Autonomic layout',
 def:'The first autonomic neuron, running from the spinal cord to the ganglion. It is myelinated and, in both divisions, releases acetylcholine onto Nn (neuronal nicotinic) receptors in the ganglion. It is long in the parasympathetic system (ganglion near or at the organ) and short in the sympathetic system.',
 hook:'Parasympathetic: long first fiber, short second fiber. Sympathetic: short first fiber, long second fiber. The first fiber always releases acetylcholine.',
 gist:'The first neuron: spinal cord to the relay, myelinated, always releases acetylcholine.',
 scene:'A myelinated neuron leaves the thoracic spinal cord, travels a short distance and releases acetylcholine onto nicotinic receptors of a cell in a cluster outside the cord.',
 confuse:['postganglionic','ganglion'],
 quote:'So typically we have a 1 to 1 fiber uh process, a very long one and a very short one, and in the ganglia, we\'re gonna have acetylcholine activating an NN for neuronal.',
 cite:'Autonomic Nervous System.pdf slides 12, 21–23; transcript 9/30; transcript 10/1',
 src:'both'},

{id:'postganglionic', term:'Postganglionic fiber', lecture:'L07', group:'Autonomic layout',
 def:'The second autonomic neuron, running from the ganglion to the organ; it is generally unmyelinated. Parasympathetic ones release acetylcholine onto muscarinic receptors; sympathetic ones release norepinephrine onto α and β receptors (exception: the sympathetic supply of the salivary glands releases acetylcholine onto M3).',
 gist:'Ganglion to organ, unmyelinated; acetylcholine or norepinephrine onto the organ’s receptors.',
 scene:'An unmyelinated neuron leaves a cluster of nerve cells beside the spine and runs all the way to the heart, where it releases norepinephrine onto β1 receptors.',
 confuse:['preganglionic','ganglion'],
 quote:'Autonomic post-ganglionic nerves generally are Non-myelinated, while Somatic are myelinated',
 cite:'Autonomic Nervous System.pdf slides 12, 29–30, 40; transcript 9/30; transcript 10/1',
 src:'both'},

{id:'ganglion', term:'Ganglion (autonomic)', lecture:'L07', group:'Autonomic layout',
 def:'The synapse between the first and second autonomic neurons, located away from the spinal cord (distal ganglia outside the cerebrospinal axis). In both the sympathetic and the parasympathetic system acetylcholine is released there onto Nn (neuronal nicotinic) receptors, so a drug that activates or blocks Nn affects both divisions at once.',
 gist:'The relay synapse itself, away from the cord; Nn receptors in both divisions.',
 scene:'Nicotine from a cigarette stimulates the relay stations between the spinal cord and the organs, so sympathetic and parasympathetic outflow rise together and blood pressure goes up.',
 confuse:['preganglionic','nn'],
 quote:'any drug that can activate the nicotinic N receptor or block it is going to affect your parasympathetic and sympathetic equally, right?',
 cite:'Autonomic Nervous System.pdf slide 12; transcript 9/30; transcript 10/1',
 src:'both'},

{id:'dual-innervation', term:'Dual innervation', lecture:'L07', group:'Autonomic layout',
 def:'Most end organs receive both parasympathetic and sympathetic fibers, which usually act in opposition. In the heart, acetylcholine on M2 lowers the heart rate and norepinephrine on β1 raises it; the division in charge at rest sets the organ’s state.',
 hook:'Exceptions: single innervation (lungs; blood vessels and kidneys), cooperation (salivary glands, male sex organ), and the GI tract, where sympathetic α2 sits on the parasympathetic terminal and cuts acetylcholine release.',
 gist:'Most organs get both divisions, and the two usually oppose each other.',
 scene:'In the heart, acetylcholine at M2 slows the rate while norepinephrine at β1 speeds it; whichever side is more active sets the beat.',
 confuse:['single-innervation','cooperating-innervation','messenger-crosstalk'],
 quote:'And so remember that for most of our organs, we have this dual innervation. We have a parasympathetic fiber releasing acetylcholine and it\'s slowing down your heart rate. We have a sympathetic fiber if you need to fight or flight that is going to release norepinephrine and going to speed up your heart rate.',
 cite:'Autonomic Nervous System.pdf slides 30, 37–38, 45–47; transcript 10/1',
 src:'both'},

{id:'single-innervation', term:'Single innervation', lecture:'L07', group:'Autonomic layout',
 def:'The exceptions to dual innervation: the lungs have only parasympathetic innervation (acetylcholine on M3, bronchial constriction; their β2 receptors are reached by adrenal epinephrine), and the blood vessels and kidneys have only sympathetic innervation (α1 vasoconstriction; β1 renin release, sodium and water retention).',
 hook:'An answer with “only” is usually wrong; for these organs it is right.',
 gist:'Lungs only parasympathetic; blood vessels and kidneys only sympathetic.',
 scene:'No nerve releases norepinephrine onto the bronchi, and no nerve releases acetylcholine onto the resistance arteries or the kidneys.',
 confuse:['dual-innervation','cooperating-innervation'],
 quote:'The lungs, only parasympathetic, the blood vessels in the kidney, only sympathetic, OK? Those are the only kind of questions you\'re gonna get that actually gonna be right if I ask you.',
 cite:'Autonomic Nervous System.pdf slides 30, 39–44; transcript 10/1',
 src:'both'},

{id:'cooperating-innervation', term:'Cooperating innervation (exception)', lecture:'L07', group:'Autonomic layout',
 def:'The exception to opposition: in the salivary glands and the male sex organ the parasympathetic and sympathetic systems work together. Both cause salivation (the sympathetic fibers to the salivary glands release acetylcholine onto M3), and in the male sex organ the parasympathetic gives erection and the sympathetic ejaculation (“point and shoot”).',
 gist:'Both divisions push the same way: salivation from both; point and shoot.',
 scene:'Activating the fight-or-flight division produces salivation, and so does activating the rest-and-digest division.',
 confuse:['dual-innervation','single-innervation'],
 quote:'Remember, both parasympathetic and sympathetic causes salivation, right?',
 cite:'Autonomic Nervous System.pdf slides 29–30, 44; transcript 10/1',
 src:'both'},

{id:'adrenal-medulla', term:'Adrenal medulla', lecture:'L07', group:'Autonomic layout',
 def:'A sympathetic exception: the preganglionic fiber releases acetylcholine onto a nicotinic receptor on the adrenal medulla instead of an adrenergic receptor, and the gland releases epinephrine and norepinephrine (about 80% to 20%) into the blood. Circulating epinephrine is how the non-innervated β2 receptors are activated (bronchial dilation, vasodilation in skeletal muscle).',
 hook:'A patient without adrenal glands cannot bronchodilate well: the lungs have no sympathetic nerves.',
 gist:'Acetylcholine on its nicotinic receptor sends epinephrine into the blood to reach β2.',
 scene:'A dog chases a runner; a gland sitting on top of the kidney pours epinephrine into the blood, and the airways open although no sympathetic nerve reaches the bronchi.',
 confuse:['beta2','cooperating-innervation'],
 quote:'your adrenal glands on top of your kidneys are going to produce norepinephrine, epinephrine at about like 80 to 20 ratio',
 cite:'Autonomic Nervous System.pdf slides 29–30, 35; transcript 9/30; transcript 10/1; transcript 10/8',
 src:'both'},

{id:'predominant-tone', term:'Predominant tone', lecture:'L07', group:'Autonomic layout',
 def:'The division that controls an organ at rest: parasympathetic in the heart, eye, lungs, GI tract, bladder and glands; sympathetic (vasoconstriction) in the blood vessels. Blocking that division lets the other one show: atropine leaves the sympathetic side unopposed (tachycardia, mydriasis). When two systems oppose each other in one organ, the one with this tone wins.',
 gist:'The division in charge at rest; blocking it lets the other side show.',
 scene:'Atropine is given and the heart rate rises and the pupils widen, because the resting control of both organs was parasympathetic and the sympathetic side is now unopposed.',
 confuse:['dual-innervation','messenger-crosstalk'],
 quote:'So, who is the predominant physiological tone in the lungs? Who is in charge? Parasympathetic, right? Because that\'s the only one there',
 cite:'Autonomic Nervous System.pdf slide 28; PCOL-Cholinergic-26s.pdf slides 13, 19; transcript 10/1; transcript 10/7',
 src:'both'},

{id:'baroreceptor-reflex', term:'Baroreceptor reflex', lecture:'L07', group:'Autonomic layout',
 def:'Short-term control of blood pressure. Baroreceptors (pressoreceptors: pressure-gated ion channels in the wall of the carotid sinus, glossopharyngeal nerve IX, and the aortic arch, vagus nerve X) fire more as pressure rises. Firing is inverse to sympathetic activity: more firing raises parasympathetic and lowers sympathetic tone, so blood pressure falls; silent baroreceptors leave the sympathetic system unopposed, so blood pressure rises.',
 hook:'Drugs set it off too: a vasodilator such as prazosin silences the baroreceptors and the heart speeds up.',
 gist:'More stretch, more firing, less sympathetic; silent receptors let pressure rise.',
 scene:'A person stands up from lying down, blood pools in the legs, and within a beat the pressure sensors in the neck and aortic arch fire less, so sympathetic tone rises and the person does not faint.',
 confuse:['reflex-tachycardia','predominant-tone'],
 quote:'So, the rule of thumb that we\'re gonna have is that the barrel receptor firing is gonna be inverse proportional to the sympathetic activity.',
 cite:'Autonomic Nervous System.pdf slides 48–52; transcript 10/1',
 src:'both'},

/* ---------------- Autonomic receptors ---------------- */
{id:'cholinergic', term:'Cholinergic', lecture:'L07', group:'Autonomic receptors',
 def:'Using acetylcholine as the transmitter. Cholinergic fibers are the preganglionic fibers of both divisions, the parasympathetic postganglionic fibers and the somatic motor fibers. Cholinergic receptors are nicotinic (Nn, Nm: ion channels; nerve and skeletal muscle) and muscarinic (M1, M2, M3: G protein–coupled; most organs).',
 gist:'Uses acetylcholine; its receptors are nicotinic and muscarinic.',
 scene:'A nerve ending releases acetylcholine, which opens nicotinic channels on a skeletal muscle and, at another site, activates muscarinic receptors on the heart.',
 confuse:['adrenergic','nn'],
 quote:'So, which receptors are involved in the cholinergic system? Muscarinics and nicotinic, but which receptor is the most organs? Muscarinic, right? Nicotinic is nerve and skeletal muscle. That\'s it.',
 cite:'Autonomic Nervous System.pdf slides 12–13; transcript 9/30',
 src:'both'},

{id:'adrenergic', term:'Adrenergic', lecture:'L07', group:'Autonomic receptors',
 def:'Using norepinephrine (or epinephrine) as the transmitter. Adrenergic fibers are the sympathetic postganglionic fibers; adrenergic receptors are α1 (Gq), α2 (Gi) and β1, β2, β3 (all Gs). Norepinephrine is made from tyrosine through L-dopa and dopamine, recycled by the norepinephrine transporter (NET) and broken down by monoamine oxidase (MAO) and catechol-O-methyltransferase (COMT).',
 gist:'Uses norepinephrine or epinephrine; its receptors are α1, α2 and β1–β3.',
 scene:'A sympathetic fiber to the heart releases norepinephrine onto β1 receptors, and the same transmitter acts on α1 receptors in the arterioles.',
 confuse:['cholinergic','catecholamine'],
 quote:'So remember that we said that at the organ, we\'re always gonna have adrenergic, right? Alpha 1s, beta 1s, alpha 2s, beta 2s.',
 cite:'Autonomic Nervous System.pdf slide 13; PCOL-Adrenergic_PCOL-26s_PTII_pptx.pdf slides 3, 8; transcript 10/1; transcript 10/6',
 src:'both'},

{id:'nn', term:'Nn (neuronal nicotinic receptor)', lecture:'L08', group:'Autonomic receptors',
 def:'The nicotinic receptor of neurons: a ligand-gated ion channel (Na+ in) made only of α and β subunits. It sits in the brain (α4/β2, the combination varenicline targets) and in the autonomic ganglia of both divisions (α3/β4, α3/β2), including the adrenal medulla, where acetylcholine from the preganglionic fiber activates the next cell.',
 hook:'Nn = neuron (ganglia, brain); Nm = muscle (skeletal neuromuscular junction). Swapping the two is the mistake he sees every year.',
 gist:'Ion channel in the brain and autonomic ganglia; varenicline’s α4/β2 target.',
 scene:'Varenicline, a partial agonist at the α4/β2 combination in the brain, blunts the craving for cigarettes; acetylcholine at the same channel type in the ganglia drives both sympathetic and parasympathetic outflow.',
 confuse:['nm','ganglion'],
 quote:'And if the end cannot give you a hint that it is the neuron and the M is the muscle, we\'re in trouble',
 cite:'PCOL-NMJ_PCOL_2026s_pptx.pdf slides 4, 6–8; Autonomic Nervous System.pdf slide 12; transcript 10/1',
 src:'both'},

{id:'nm', term:'Nm (muscle nicotinic receptor)', lecture:'L08', group:'Autonomic receptors',
 def:'The nicotinic receptor of skeletal muscle at the neuromuscular junction (somatic system): a ligand-gated ion channel of five subunits (α, β, γ, δ, ε; acetylcholine binds both α subunits). Opening lets Na+ in and K+ out and leads to contraction. Succinylcholine opens it (depolarizing) and curare-like drugs keep it closed (non-depolarizing); both paralyze.',
 gist:'Ion channel at the neuromuscular junction; rocuronium and succinylcholine act here.',
 scene:'Rocuronium given before surgery occupies this channel where nerve meets skeletal fiber, acetylcholine can no longer open it, and the patient cannot move.',
 confuse:['nn','depolarizing-blocker'],
 quote:'We have the NM for muscular, not smooth muscle, skeletal muscle.',
 cite:'PCOL-NMJ_PCOL_2026s_pptx.pdf slides 4, 11–15, 19; transcript 10/1; transcript 10/5',
 src:'both'},

{id:'m1', term:'M1 (muscarinic type 1)', lecture:'L09', group:'Autonomic receptors',
 def:'The muscarinic receptor of the brain: coupled to Gq, it activates phospholipase C (PLC), raises inositol trisphosphate (IP3) and Ca++, and excites. Agonists cause brain stimulation and emesis; blocking it causes sedation, and at high doses hallucinations, restlessness and coma.',
 gist:'Brain, Gq, raises calcium: excitation; blocking it sedates.',
 scene:'Oxybutynin blocks this receptor in the brain as well as M3 in the bladder, and the patient becomes drowsy and confused.',
 confuse:['m2','m3'],
 quote:'What effect they would have by affecting the M1s? What would be the site of action? The brain, right? So they\'ll cause sedation.',
 cite:'PCOL-Cholinergic-26s.pdf slides 9–10, 30, 32; Autonomic Nervous System.pdf slides 4, 24; transcript 9/30; transcript 10/5',
 src:'both'},

{id:'m2', term:'M2 (muscarinic type 2)', lecture:'L09', group:'Autonomic receptors',
 def:'The muscarinic receptor of the heart (sinoatrial and atrioventricular nodes): coupled to Gi, it inhibits adenylate cyclase (less cyclic AMP), and its βγ subunits open K+ channels, so K+ leaves and the membrane hyperpolarizes. Result: bradycardia and less contractility; blocking it (atropine) gives tachycardia.',
 gist:'Heart, Gi: less cyclic AMP, potassium out, slower rate.',
 scene:'Carbachol is given and the heart rate falls: the receptor in the nodes lowers cyclic AMP and lets potassium out until the membrane is more negative.',
 confuse:['m3','alpha2','beta1'],
 quote:'Is potassium high inside or outside of the cell? Inside, so where it wants to go outside, the more potassium it gets out, the more negative the membrane becomes, and is that what is called hyper polarization.',
 cite:'PCOL-Cholinergic-26s.pdf slides 7–10, 14, 19; transcript 10/5',
 src:'both'},

{id:'m3', term:'M3 (muscarinic type 3)', lecture:'L09', group:'Autonomic receptors',
 def:'The muscarinic receptor of “everywhere else”: smooth muscle (gut, bladder, airways), glands, the eye and the vascular endothelium (non-innervated). Coupled to Gq: phospholipase C (PLC) → inositol trisphosphate (IP3) → Ca++ → contraction or secretion (miosis, bronchial constriction, salivation, urination, diarrhea). On the endothelium the Ca++ activates nitric oxide synthase instead, so the vessel dilates.',
 gist:'Everywhere else, Gq: squeezes smooth muscle and glands; endothelium dilates vessels.',
 scene:'Pilocarpine makes the mouth water, the pupil shrink and the bronchi narrow, all through one Gq-coupled receptor on glands and smooth muscle.',
 confuse:['m1','m2','alpha1'],
 quote:'So, M1 is in the CNS, M2 is in the heart, M3s everywhere else. I can switch the everywhere from a 3 to a, from an E to a 3 so that you can remember that M3s are the most widespread',
 cite:'Autonomic Nervous System.pdf slides 4, 13, 24; PCOL-Cholinergic-26s.pdf slides 5–6, 9–10, 14; transcript 9/30; transcript 10/5',
 src:'both'},

{id:'alpha1', term:'α1 (alpha-1 adrenergic receptor)', lecture:'L10', group:'Autonomic receptors',
 def:'The adrenergic receptor coupled to Gq: phospholipase C → inositol trisphosphate (IP3) → Ca++ → smooth-muscle contraction. Sites: blood vessels (systemic arteries set afterload, veins set preload), eye (pupil dilation), nose, and the vessels of the sinus and prostate (“I see and smell bloody urine”). Agonist phenylephrine constricts; antagonist prazosin dilates.',
 gist:'Gq on vascular smooth muscle: calcium up, vessels constrict, pupils dilate.',
 scene:'Phenylephrine nasal spray shrinks the swollen vessels in the nose and also widens the pupil, both through raised calcium in smooth muscle.',
 confuse:['alpha2','m3','beta2'],
 quote:'So, alpha ones are in all the places, as we\'re gonna talk about it, but the blood vessels are their number one job.',
 cite:'PCOL-Adrenergic_PCOL-26s_PTII_pptx.pdf slides 3, 17–18; Autonomic Nervous System.pdf slide 13; transcript 9/30; transcript 10/6',
 src:'both'},

{id:'alpha2', term:'α2 (alpha-2 adrenergic receptor)', lecture:'L10', group:'Autonomic receptors',
 def:'The adrenergic receptor coupled to Gi (an inhibitory receptor): it inhibits adenylate cyclase and lowers cyclic AMP. It sits on nerve endings (primarily in the brain), in the GI tract (on the parasympathetic terminal, where it cuts acetylcholine release) and on the β cells of the pancreas. Agonist clonidine lowers norepinephrine release and sympathetic tone; antagonist mirtazapine raises them.',
 gist:'Gi on nerve endings: less transmitter released, less sympathetic tone, sedation.',
 scene:'Clonidine lowers a patient’s blood pressure and heart rate, dries the mouth and makes him sleepy, by acting on the nerve endings that release norepinephrine.',
 confuse:['alpha1','m2'],
 quote:'Because alpha 1 agonist constrict, alpha 2 relax because one is exciting, the other one is inhibiting. Remember, alpha 2 is G alpha I, alpha 1 is G alpha Q.',
 cite:'PCOL-Adrenergic_PCOL-26s_PTII_pptx.pdf slides 3, 8, 21–24; Autonomic Nervous System.pdf slides 45–47; transcript 10/1; transcript 10/6',
 src:'both'},

{id:'beta1', term:'β1 (beta-1 adrenergic receptor)', lecture:'L11', group:'Autonomic receptors',
 def:'The adrenergic receptor coupled to Gs, located primarily in the heart and kidney: it activates adenylate cyclase and raises cyclic AMP and cytosolic Ca++. In the heart it raises rate, force, conduction and the rate of relaxation (cardiac output); on the juxtaglomerular cells of the kidney it releases renin. Selective agonist dobutamine; selective antagonist metoprolol.',
 gist:'Gs in heart and kidney: faster, stronger beat and renin release.',
 scene:'Dobutamine given intravenously to a failing heart raises its force and rate by raising cyclic AMP, and the kidney releases more renin.',
 confuse:['beta2','m2','beta3'],
 quote:'So, if it\'s beta one receptors, which G protein is, GS GS is gonna be AC in camp, which is gonna cause heart rate to go up.',
 cite:'PCOL-Adrenergic_PCOL-26s_PTII_pptx.pdf slides 3, 40–41, 56; transcript 9/30; transcript 10/7',
 src:'both'},

{id:'beta2', term:'β2 (beta-2 adrenergic receptor)', lecture:'L11', group:'Autonomic receptors',
 def:'The adrenergic receptor coupled to Gs on smooth muscle (bronchi, the blood vessels of skeletal muscle, gut; also brain and eye): more cyclic AMP relaxes the muscle, so it dilates the airways and those vessels. It is typically not innervated: circulating epinephrine from the adrenal medulla activates it. Agonist albuterol (the -terols).',
 gist:'Gs on smooth muscle: relaxes bronchi and vessels; reached by blood epinephrine, no nerve.',
 scene:'An albuterol inhaler opens the airways of a patient with asthma by raising cyclic AMP, at a site that no sympathetic nerve reaches directly.',
 confuse:['beta1','beta3','alpha1'],
 quote:'Our beta 2s are not innervated. They don\'t have a nerve activating them.',
 cite:'PCOL-Adrenergic_PCOL-26s_PTII_pptx.pdf slides 3, 42–43; Autonomic Nervous System.pdf slides 13, 35, 42; transcript 9/30; transcript 10/7',
 src:'both'},

{id:'beta3', term:'β3 (beta-3 adrenergic receptor)', lecture:'L11', group:'Autonomic receptors',
 def:'The adrenergic receptor coupled to Gs (more cyclic AMP) expressed in the bladder: activation relaxes the detrusor muscle and increases bladder capacity, so urine is held. Agonist mirabegron treats overactive bladder without the dry mouth and constipation of the muscarinic antagonists.',
 gist:'Gs in the bladder: relaxes the detrusor and holds urine; mirabegron.',
 scene:'Mirabegron relaxes the bladder wall of a patient with an overactive bladder, and unlike trospium it does not dry the mouth.',
 confuse:['m3','beta2'],
 quote:'In the bladder, we have beta 3s on the smooth muscle of the bladder, and that\'s going to relax the bladder so that way patients don\'t have to feel like urinating all the time.',
 cite:'PCOL-Adrenergic_PCOL-26s_PTII_pptx.pdf slides 3, 44; Autonomic Nervous System.pdf slide 31; transcript 10/7',
 src:'both'},

/* ---------------- Cholinergic drugs ---------------- */
{id:'dumbbelss', term:'DUMBBELSS (cholinergic crisis)', lecture:'L07', group:'Cholinergic drugs',
 def:'The effects of over-activating the cholinergic (muscarinic) system: Diarrhea, Urination, Miosis, Bradycardia, Bronchial constriction, Emesis, Lacrimation, Salivation, Stimulation of the brain. Produced by muscarinic agonists (carbachol, pilocarpine), cholinesterase inhibitors (the -stigmines, donepezil) and organophosphates.',
 hook:'Miosis (short word, small pupil) is on the list; mydriasis (long word, large pupil) is not.',
 gist:'Muscarinic overload: diarrhea, urination, small pupils, slow heart, wheeze, tears, saliva.',
 scene:'A farm worker exposed to an insecticide arrives with diarrhea, frequent urination, pinpoint pupils, a slow heart, wheezing, vomiting, tears and drooling.',
 confuse:['anti-dumbbelss','organophosphate'],
 quote:'So, when we have an agonist that activates your parasympathetic, your cholinergic system, you\'re gonna be getting the dumbbells. Not very pleasant, right?',
 cite:'Autonomic Nervous System.pdf slides 24, 26–27; PCOL-Cholinergic-26s.pdf slides 13, 15; transcript 9/30; transcript 10/5',
 src:'both'},

{id:'anti-dumbbelss', term:'Anti-DUMBBELSS', lecture:'L09', group:'Cholinergic drugs',
 def:'The opposite of the cholinergic crisis, from blocking muscarinic receptors (atropine, the -tropiums, oxybutynin, trospium): constipation, urinary retention, mydriasis and blurred vision, tachycardia, bronchial dilation, dry mouth, and in the brain hallucinations, restlessness and coma. Atropine toxicity: dry as a bone, hot as a pistol, red as a beet, blind as a bat, mad as a hatter.',
 gist:'Cannot poop, cannot pee, cannot see, fast heart, dry mouth: muscarinic block.',
 scene:'After an overdose of atropine a patient is flushed, hot and dry-mouthed, constipated and unable to urinate, with wide pupils and a racing heart.',
 confuse:['dumbbelss'],
 quote:'The antagonists cause what? Anti dumbbells. You can\'t poop, can\'t pee, can\'t see because your pupils dilate. You get tachycardia. You get the opposite effect.',
 cite:'PCOL-Cholinergic-26s.pdf slides 18–19, 30, 32; Autonomic Nervous System.pdf slide 24; transcript 9/30; transcript 10/5',
 src:'both'},

{id:'cholinesterase-inhibitor', term:'Cholinesterase inhibitor (indirect antagonist)', lecture:'L08', group:'Cholinergic drugs',
 def:'A drug that acts somewhere other than the receptor, upstream or downstream of it. His example: acetylcholinesterase inhibitors (the -stigmines, donepezil, rivastigmine) bind the enzyme that breaks down acetylcholine, so acetylcholine rises at every synapse where it is released, becomes more potent at its receptors and gives DUMBBELSS. They reverse curare-like drugs.',
 hook:'Despite the name it raises acetylcholine: the enzyme, not the receptor, is antagonized.',
 gist:'Acts off the receptor: blocks the enzyme, so acetylcholine builds up everywhere.',
 scene:'Neostigmine is given to a hunter paralyzed by a curare-tipped arrow; more acetylcholine stays in the synapse and outcompetes curare at the muscle.',
 confuse:['organophosphate','nondepolarizing-blocker'],
 quote:'How would you classify tomorrow on the exam for me if I ask you about an indirect antagonist? Either downstream or upstream from the receptor, it\'s binding anywhere else but the receptor.',
 cite:'PCOL-NMJ_PCOL_2026s_pptx.pdf slides 10–12, 33–37; transcript 10/1; transcript 10/5',
 src:'both'},

{id:'depolarizing-blocker', term:'Depolarizing blocker (succinylcholine)', lecture:'L08', group:'Cholinergic drugs',
 def:'A neuromuscular blocker that is an agonist at the Nm receptor. Succinylcholine (two acetylcholine molecules joined) opens the channels all at once and, because it is not broken down quickly, the end plate stays depolarized and cannot reprime, so the muscle is paralyzed; with prolonged infusion it lodges in the channel pore. Longer or higher doses reach ganglionic Nn: hypertension and arrhythmias. Also hyperkalemia and myalgia.',
 gist:'An agonist that holds the muscle channel open until the end plate cannot reset.',
 scene:'For a rapid intubation, a drug resembling two acetylcholine molecules opens every channel on the end plate at once; the fibers twitch out of sync and then go limp.',
 confuse:['nondepolarizing-blocker','phase-1-block'],
 quote:'depolarizing, which is the same thing as an agonist, it is activating the receptors, and non-depolarizing, which is gonna be the antagonist.',
 cite:'PCOL-NMJ_PCOL_2026s_pptx.pdf slides 19–25; transcript 10/5',
 src:'both'},

{id:'nondepolarizing-blocker', term:'Curare-like (non-depolarizing) blocker', lecture:'L08', group:'Cholinergic drugs',
 def:'A competitive, reversible Nm antagonist (curare/tubocurarine and the -curoniums: rocuronium, vecuronium, pancuronium; atracurium). It binds the two α subunits and stops acetylcholine from opening the channel, so skeletal muscle is paralyzed (eyes, jaw and larynx first, then the limbs, then the diaphragm). More acetylcholine from a cholinesterase inhibitor such as neostigmine outcompetes it. No central nervous system effect.',
 gist:'Competitive, reversible antagonist at the muscle channel; neostigmine reverses it.',
 scene:'A hunter grazed by an arrow tip dipped in a rainforest plant extract cannot move; neostigmine, which raises acetylcholine at the junction, lets him move again.',
 confuse:['depolarizing-blocker','cholinesterase-inhibitor'],
 quote:'But for our purpose on exam two, all I need you to know is that any karate-like drug is what? A competitive, reversible NM antagonist, and by blocking the NM, what are you gonna get? Paralysis, right?',
 cite:'PCOL-NMJ_PCOL_2026s_pptx.pdf slides 19, 27–32; transcript 10/5',
 src:'both'},

{id:'phase-1-block', term:'Phase I block', lecture:'L08', group:'Cholinergic drugs',
 def:'Succinylcholine’s first mechanism: as an agonist it opens the Nm channels all at once, but it is not metabolized effectively at the synapse, so the motor end plate stays depolarized. Excitation–contraction coupling needs repolarization of the end plate (“repriming”) and repetitive firing, so the muscle is paralyzed.',
 gist:'Channels opened at once; the end plate stays depolarized and cannot reprime.',
 scene:'Seconds after succinylcholine, every channel on the end plate is open and the membrane cannot reset to fire again, so the muscle stays slack.',
 confuse:['phase-2-block','depolarizing-blocker'],
 quote:'And the first one is that opening of all the receptors. That\'s called phase one.',
 cite:'PCOL-NMJ_PCOL_2026s_pptx.pdf slides 21–22, 24; transcript 10/5',
 src:'both'},

{id:'phase-2-block', term:'Phase II block', lecture:'L08', group:'Cholinergic drugs',
 def:'Succinylcholine’s second mechanism, with prolonged infusion: the molecule lodges inside the Nm channel pore, so Na+ and K+ cannot move through it and the paralysis is prolonged.',
 gist:'With prolonged infusion the drug sticks inside the channel pore; ions cannot pass.',
 scene:'During a long infusion of succinylcholine some molecules get stuck in the pore of the nicotinic channel, and sodium can no longer pass through it.',
 confuse:['phase-1-block','nondepolarizing-blocker'],
 quote:'And then if it stays around longer, now it actually can get lodged inside of that channel. And that will be a phase 2. Now it\'s blocking anything from going through.',
 cite:'PCOL-NMJ_PCOL_2026s_pptx.pdf slides 23–24; transcript 10/5',
 src:'both'},

{id:'organophosphate', term:'Organophosphate', lecture:'L08', group:'Cholinergic drugs',
 def:'An irreversible cholinesterase inhibitor: it forms a covalent bond with the enzyme (it phosphorylates it) that is very stable and slow. Insecticides (malathion, parathion), nerve gas (sarin, soman, tabun) and the eye drug echothiophate. Well absorbed through skin, lung, gut and conjunctiva; poisoning gives DUMBBELSS plus stimulation of the ganglia, the neuromuscular junction (paralysis of the diaphragm) and the brain.',
 gist:'Covalent, irreversible block of the enzyme: insecticides, nerve gas, echothiophate.',
 scene:'A man sprinkles a farm pesticide on his hamburger, and the enzyme that clears acetylcholine is bound for good: drooling, wheezing and a slow heart, then a weak diaphragm.',
 confuse:['cholinesterase-inhibitor','pralidoxime'],
 quote:'Remember those drugs are irreversible. They form covalent bonds, which means that now we have too much acetylcholine going around.',
 cite:'PCOL-NMJ_PCOL_2026s_pptx.pdf slides 42–45; PCOL-Cholinergic-26s.pdf slides 20–23; transcript 10/5',
 src:'both'},

{id:'pralidoxime', term:'Pralidoxime (cholinesterase reactivator, 2-PAM)', lecture:'L08', group:'Cholinergic drugs',
 def:'The antidote that dephosphorylates the cholinesterase enzyme bound by an organophosphate, breaking the covalent bond and regenerating the enzyme. It must be given early (within about an hour of exposure); the longer the wait, the tighter the bond, until it cannot be broken. Atropine (M1, M2, M3 antagonist) is then given to manage the DUMBBELSS, which pralidoxime does not stop.',
 gist:'Antidote that frees the poisoned enzyme from its phosphate bond; works only early.',
 scene:'An insecticide-poisoned farm worker reaches the hospital within the hour; the first drug given frees the enzyme from its phosphate bond, and atropine follows for the drooling and wheezing.',
 confuse:['organophosphate','anti-dumbbelss'],
 quote:'If you wait too long, that bone becomes tighter and tighter and tighter, and you can\'t break it. So you gotta use within an hour of exposure to organic phosphate, and then you just use atropine to manage the patient after that',
 cite:'PCOL-NMJ_PCOL_2026s_pptx.pdf slide 44; transcript 10/5',
 src:'both'},

{id:'quaternary-amine', term:'Quaternary amine', lecture:'L08', group:'Cholinergic drugs',
 def:'A positively charged structure that does not cross the blood–brain barrier: neostigmine and pyridostigmine stay in the periphery (myasthenia gravis, reversing curare-like drugs), and echothiophate is poorly absorbed from the eye. The tertiary amine physostigmine readily enters the central nervous system (antidote for atropine poisoning).',
 gist:'Charged, so it stays outside the brain: neostigmine, pyridostigmine, echothiophate.',
 scene:'For a patient with myasthenia gravis, neostigmine is chosen over physostigmine because its charged nitrogen keeps it out of the brain and away from central side effects.',
 confuse:['cholinesterase-inhibitor','nondepolarizing-blocker'],
 quote:'So neo stigamine, which does not cross the blood brain barrier but can increase the levels of acetylcholine in the synapse of your skeletal muscle, would give you a better chance of outcompeting karate',
 cite:'PCOL-NMJ_PCOL_2026s_pptx.pdf slides 39, 45; transcript 10/5',
 src:'both'},

{id:'snare', term:'SNARE proteins (botulinum toxin target)', lecture:'L08', group:'Cholinergic drugs',
 def:'The anchoring proteins that dock an acetylcholine vesicle at the presynaptic membrane so it can fuse and release its contents by exocytosis. Botulinum toxin is an endopeptidase that cleaves them, so acetylcholine cannot be released and the muscle relaxes (crow’s feet, excessive drooling).',
 gist:'Vesicle docking anchors; cut them and acetylcholine cannot be released.',
 scene:'An injection beside the eyes smooths crow’s feet: the vesicles in the nerve ending stay full of acetylcholine because the docking anchors have been cut.',
 confuse:['nondepolarizing-blocker','cholinesterase-inhibitor'],
 quote:'So Botox is an enzyme that breaks down the snare protein, and if you don\'t have the snare protein, your vesicles can\'t bind properly and thus you can\'t release the cetylcholine.',
 cite:'PCOL-NMJ_PCOL_2026s_pptx.pdf slides 46–50; transcript 10/5',
 src:'both'},

/* ---------------- Adrenergic drugs ---------------- */
{id:'catecholamine', term:'Catecholamine', lecture:'L11', group:'Adrenergic drugs',
 def:'The endogenous transmitters norepinephrine, epinephrine and dopamine (made from tyrosine → L-dopa → dopamine → norepinephrine). They control heart rate and force, blood pressure, insulin release and fat breakdown, and are broken down by monoamine oxidase (MAO) and catechol-O-methyltransferase (COMT).',
 gist:'Norepinephrine, epinephrine and dopamine; made from tyrosine, cleared by two enzymes.',
 scene:'Tyrosine in a sympathetic nerve ending is turned into L-dopa, then dopamine, then norepinephrine, and the adrenal gland adds epinephrine to the blood.',
 confuse:['adrenergic','mao-a'],
 quote:'We have type A and then we have type B, OK? And those are involved in the breakdown of catecholamines, norepinephrine, epinephrine, dopamine, and so on.',
 cite:'PCOL-Adrenergic_PCOL-26s_PTII_pptx.pdf slides 8, 46; transcript 10/6; transcript 10/7',
 src:'both'},

{id:'mao-a', term:'MAO-A (monoamine oxidase A)', lecture:'L10', group:'Adrenergic drugs',
 def:'The form of monoamine oxidase in the gut (slide: brain, liver and GI tract) that breaks down norepinephrine and dopamine, including dietary tyramine. Non-selective inhibitors that block MAO-A and MAO-B (phenelzine, irreversible) raise stored norepinephrine for depression but make tyramine-rich food dangerous (hypertensive crisis).',
 gist:'The gut form: breaks down norepinephrine, dopamine and dietary tyramine.',
 scene:'Phenelzine stops the enzyme in the intestine from breaking down the tyramine in aged, fermented food, and the blood pressure climbs to a crisis.',
 confuse:['mao-b','cheese-effect'],
 quote:'they can inhibit both enzymes, the MAOA that is in the gut, as well as the MAOB that is for the brain. So if you\'re not sure, think about B for brain',
 cite:'PCOL-Adrenergic_PCOL-26s_PTII_pptx.pdf slides 13–15; transcript 10/6',
 src:'both'},

{id:'mao-b', term:'MAO-B (monoamine oxidase B)', lecture:'L10', group:'Adrenergic drugs',
 def:'The form of monoamine oxidase in the brain (striatum) that breaks down dopamine. Selegiline (low doses) is a selective, irreversible inhibitor of it, used for depression and Parkinson’s disease; because the gut enzyme is spared, it causes no tyramine crisis.',
 gist:'The brain form, breaks down dopamine; selegiline blocks it with no tyramine problem.',
 scene:'Selegiline at a low dose raises dopamine in the striatum of a patient with Parkinson’s disease, and the patient may still eat aged cheese.',
 confuse:['mao-a','cheese-effect'],
 quote:'So there is no cheese effect with the selective irreversible MAOB inhibitors in that process.',
 cite:'PCOL-Adrenergic_PCOL-26s_PTII_pptx.pdf slides 13–15; transcript 10/6',
 src:'both'},

{id:'net-blocker', term:'Reuptake inhibitor at the NET (cocaine)', lecture:'L10', group:'Adrenergic drugs',
 def:'An indirect-acting adrenergic drug that blocks the norepinephrine transporter (NET), the route that carries released norepinephrine back into the nerve ending to be stored again. Norepinephrine stays in the synapse and acts longer on postsynaptic receptors (heart, blood vessels, brain). Cocaine is a complete NET blocker.',
 gist:'Blocks the norepinephrine transporter, so norepinephrine stays in the synapse longer.',
 scene:'A recreational user’s nose bleeds and the septum is damaged: norepinephrine released onto the nasal vessels is no longer carried back into the nerve ending, and the vessels clamp down.',
 confuse:['releasing-agent','mao-a'],
 quote:'So cocaine is a reuptake inhibitor. This drug blocks the net transporter, and if I block the net transporter, what is going to happen to the levels of norepinephrine? Would increase',
 cite:'PCOL-Adrenergic_PCOL-26s_PTII_pptx.pdf slides 8–10; transcript 10/6',
 src:'both'},

{id:'releasing-agent', term:'Releasing agent (amphetamine)', lecture:'L10', group:'Adrenergic drugs',
 def:'An indirect-acting drug whose primary action is to stimulate presynaptic release of norepinephrine, dopamine and serotonin (dextroamphetamine, amphetamine, lisdexamfetamine, methylphenidate); secondarily it weakly blocks the transporter and monoamine oxidase. Effects: focus, energy, less sleep and appetite, plus tremor, sweating, raised heart rate and blood pressure, and hyperthermia.',
 gist:'Pushes norepinephrine, dopamine and serotonin out of the nerve ending.',
 scene:'A person takes a stimulant prescribed for attention deficit before a test; nerve endings pour out norepinephrine and dopamine, the hands tremble, the heart races and appetite disappears.',
 confuse:['net-blocker','catecholamine'],
 quote:'They are indirectly enhancing the release, so they stimulate the release of catecholamine, such as norepinephrine, serotonin, and dopamine, OK?',
 cite:'PCOL-Adrenergic_PCOL-26s_PTII_pptx.pdf slides 9, 11–12; transcript 10/6',
 src:'both'},

{id:'cheese-effect', term:'Cheese effect (tyramine)', lecture:'L10', group:'Adrenergic drugs',
 def:'The hypertensive crisis that follows eating tyramine-rich fermented foods (cheese, bread, wine) while taking a non-selective MAO-A and MAO-B inhibitor such as phenelzine: the gut enzyme can no longer break down dietary tyramine. Selective MAO-B inhibitors (selegiline at low doses) do not cause it.',
 gist:'Fermented food plus a non-selective enzyme blocker: a blood pressure crisis.',
 scene:'A man taking phenelzine forgets his diet at a party, eats aged fermented food with wine, and his blood pressure soars until he passes out and an ambulance is called.',
 confuse:['mao-a','rebound-hypertension'],
 quote:'And the reason being is because you have the inability to break down that dietary tyramine that you\'re consuming, and those fermented foods have high levels of tyramine, and that can cause what is called a hypertensive crisis.',
 cite:'PCOL-Adrenergic_PCOL-26s_PTII_pptx.pdf slide 15; transcript 10/6',
 src:'both'},

{id:'epinephrine-reversal', term:'Epinephrine reversal', lecture:'L11', group:'Adrenergic drugs',
 def:'Epinephrine’s affinity order is β1 and β2 first, then α1, then α2. Low doses act on β2 in blood vessels and dilate them; high doses add α1, which overrides β2 and constricts (net pressor effect). After an α1 antagonist such as prazosin the same high dose lowers blood pressure (net depressor effect): the response is reversed. Phenylephrine (α1 only) is abolished, not reversed, by prazosin.',
 hook:'Propranolol does the opposite: it removes β2, so the constriction grows (compound 1 in his Jeopardy question).',
 gist:'Low dose dilates, high dose constricts; after prazosin the high dose dilates.',
 scene:'In a blood vessel, a low dose of the adrenal hormone dilates it through β2, a high dose constricts it through α1, and after prazosin even the high dose dilates.',
 confuse:['messenger-crosstalk','reflex-tachycardia'],
 quote:'That\'s how we explain a phenomenon that we observe which is called epinephrine reversal, which means that at low doses, epinephrine is causing vasodilation, but a higher dose is going to cause vasoconstriction.',
 cite:'PCOL-Adrenergic_PCOL-26s_PTII_pptx.pdf slides 47–51; transcript 10/7; transcript 10/8',
 src:'both'},

{id:'beta1-selective-blocker', term:'β1-selective blocker (MAN)', lecture:'L11', group:'Adrenergic drugs',
 def:'β blockers that block β1 and leave β2 alone at usual doses: metoprolol, atenolol and nebivolol (“MAN”). Every β blocker blocks β1 (lower heart rate, contractility, cardiac output and renin), but these spare the β2 of the lungs, so they are the choice in asthma, and they leave the tremor and nervousness that warn of hypoglycemia. Metoprolol reaches the brain poorly.',
 hook:'Twins poll: the twin on metoprolol finishes the 5k first, because he can still breathe.',
 gist:'Block the heart’s β1 and spare the lungs’ β2: usable in asthma.',
 scene:'A patient with asthma needs his heart rate slowed; the drug chosen slows the heart and leaves the airways alone, and he can still breathe during a run.',
 confuse:['nonselective-beta-blocker','beta1'],
 quote:'So, we have metoprolol, atenolol, and nabivolol. Those are gonna be your beta one selectives, right?',
 cite:'PCOL-Adrenergic_PCOL-26s_PTII_pptx.pdf slides 54, 56, 59; transcript 10/7',
 src:'both'},

{id:'nonselective-beta-blocker', term:'Non-selective β blocker (propranolol)', lecture:'L11', group:'Adrenergic drugs',
 def:'A β blocker that blocks β1 and β2: propranolol (the prototype) and pindolol (a partial agonist); carvedilol and labetalol block α1 as well. Blocking lung β2 narrows the airways (careful in asthma). Propranolol is lipophilic and blocks central β2, lowering anxiety. These drugs mask the tremor and nervousness of hypoglycemia, leaving only sweating.',
 gist:'Blocks β1 and β2 alike, so the airways can narrow in asthma.',
 scene:'A lipophilic drug taken before a public speech slows the heart and calms the speaker by acting on β2 in the brain, but in a patient with asthma it narrows the airways.',
 confuse:['beta1-selective-blocker','beta2'],
 quote:'And then you know that your propranolol, pinolol is your beta 1, beta 2, and then your carvedilol, labetalol is your beta 1, beta 2, and alpha 1, right?',
 cite:'PCOL-Adrenergic_PCOL-26s_PTII_pptx.pdf slides 54–59; transcript 10/1; transcript 10/7',
 src:'both'},

{id:'rebound-hypertension', term:'Rebound hypertension', lecture:'L10', group:'Adrenergic drugs',
 def:'A hypertensive crisis when a drug that lowers sympathetic signaling is stopped abruptly. Months of clonidine (less norepinephrine released) or of a β blocker (receptors blocked) make the body up-regulate its adrenergic receptors; stopped “cold turkey,” normal norepinephrine meets the extra receptors. Patients must be weaned off.',
 gist:'Stopping clonidine or a β blocker suddenly: extra receptors, blood pressure spikes.',
 scene:'A patient on clonidine for months runs out on a trip and stops it at once; norepinephrine now meets the many receptors his body made, and his blood pressure shoots up.',
 confuse:['cheese-effect','first-dose-effect'],
 quote:'You cannot go cold turkey. Because if you go cold turkey, you get what hypertensive crisis, right? You\'ve been up regulating your receptors because that antagonist is lowering the function of the system.',
 cite:'PCOL-Adrenergic_PCOL-26s_PTII_pptx.pdf slides 26, 59; transcript 10/6; transcript 10/7',
 src:'both'},

{id:'first-dose-effect', term:'First-dose effect', lecture:'L10', group:'Adrenergic drugs',
 def:'A fall in blood pressure on standing, with syncope, 30–90 minutes after the first dose of a selective α1 antagonist (prazosin and the other -osins): arteries and veins relax, the sympathetic system cannot constrict them, and the patient faints on getting up. It is also listed for renin inhibitors, ACE inhibitors and ARBs.',
 hook:'The same drop gives palpitations: the heart speeds up to make up for it.',
 gist:'Fainting on standing after starting prazosin: veins and arteries cannot constrict.',
 scene:'An hour after starting prazosin, a patient gets up quickly from a chair, the room goes dark and he falls, because his veins cannot squeeze blood back to the heart.',
 confuse:['reflex-tachycardia','rebound-hypertension'],
 quote:'Prazosin’s ADR: 1st Dose Effect; Reflex tachycardia (palpitations); Orthostatic Hypotension & Syncope (30-90 min)',
 cite:'PCOL-Adrenergic_PCOL-26s_PTII_pptx.pdf slides 29–30; PCOL-RAAS_26s.pdf slide 19; transcript 10/6',
 src:'both'},

{id:'reflex-tachycardia', term:'Reflex tachycardia', lecture:'L10', group:'Adrenergic drugs',
 def:'A rise in heart rate that is not a direct drug action: a drug lowers blood pressure (an α1 antagonist dilating the arteries, or acetylcholine releasing nitric oxide), the pressure sensors in the arteries fire less, sympathetic output rises and β1 speeds the heart (palpitations). In the rat, acetylcholine lowered blood pressure and the heart rate rose although M2 slows the heart.',
 gist:'Blood pressure falls, pressure sensors fire less, sympathetic β1 speeds the heart.',
 scene:'A rat given acetylcholine intravenously shows a fall in blood pressure and, instead of the expected M2 slowing, a faster heart.',
 confuse:['baroreceptor-reflex','first-dose-effect'],
 quote:'If you vasodilate the arteries, now your barrels are gonna sense my blood pressure is too low. What is it gonna do? I\'m gonna increase the sympathetic, I\'m gonna get reflex tachycardia, so palpitations, right?',
 cite:'PCOL-Adrenergic_PCOL-26s_PTII_pptx.pdf slides 30, 77–80; transcript 10/6; transcript 10/7',
 src:'both'},

{id:'messenger-crosstalk', term:'Second-messenger cross-talk', lecture:'L11', group:'Adrenergic drugs',
 def:'Two signaling pathways acting on the same cell or messenger, so the response is their net. In the heart, acetylcholine on M2 (Gi, less cyclic AMP) and norepinephrine on β1 (Gs, more cyclic AMP) act on the same cyclic AMP and contractility, and the division with the predominant tone wins. β2 (cyclic AMP) and nitric oxide (cyclic GMP) both dilate vessels, and both messengers are broken down by phosphodiesterase, so their effects add.',
 gist:'Opposing systems: the predominant tone wins; parallel ones (cyclic AMP, cyclic GMP) add.',
 scene:'A vessel exposed to both a β2 agonist and nitroglycerin dilates more than with either alone, because cyclic AMP and cyclic GMP both relax it and one enzyme breaks down both.',
 confuse:['dual-innervation','predominant-tone'],
 quote:'And whoever has the predominant tone wins that crosstalk, right? Or that fight in between the dual uh systems that we have over here.',
 cite:'PCOL-Adrenergic_PCOL-26s_PTII_pptx.pdf slide 61; transcript 10/7',
 src:'both'},

/* ---------------- Nitric oxide ---------------- */
{id:'nitric-oxide', term:'Nitric oxide (NO)', lecture:'L11', group:'Nitric oxide',
 def:'A gas made in the endothelium that diffuses into the underlying vascular smooth muscle and causes potent vasodilation by activating soluble guanylyl cyclase (more cyclic GMP). It is very short-lived. Once considered a pollutant; when aging or damage to the endothelium cuts its production, blood pressure rises. Nitroglycerin and nitroprusside give it off as they are metabolized.',
 gist:'Endothelial gas that diffuses into smooth muscle and dilates it.',
 scene:'Acetylcholine dilates a carefully dissected artery, but in an artery whose inner lining was scraped off it does nothing, because the lining makes the dilating gas.',
 confuse:['cgmp','no-donor'],
 quote:'I need you to know that if you either activate the M3s on the endothelium or if you take nitroglycerin, you\'re going to be either producing nitric oxide, and nitric oxide is a powerful vasodilator',
 cite:'PCOL-Adrenergic_PCOL-26s_PTII_pptx.pdf slides 62, 64, 67, 74; transcript 10/7',
 src:'both'},

{id:'nos', term:'NOS (nitric oxide synthase)', lecture:'L11', group:'Nitric oxide',
 def:'The endothelial enzyme that converts L-arginine to L-citrulline and releases nitric oxide as a byproduct (it needs NADPH, O2 and calcium–calmodulin). M3 on the endothelium (Gq → IP3 → Ca++ from the endoplasmic reticulum → calcium–calmodulin) activates it, so Gq here causes dilation, not constriction.',
 gist:'Endothelial enzyme: L-arginine to L-citrulline, switched on by calcium–calmodulin.',
 scene:'Carbachol binds M3 on the inner lining of an artery, calcium rises and binds calmodulin, and an enzyme turns L-arginine into L-citrulline.',
 confuse:['sgc','nitric-oxide'],
 quote:'So what this nitric oxide synthase does, the NOS enzyme, is they can convert an amino acid, the L arginine, into the L-citrullin. And as a byproduct of that, you get nitric oxide.',
 cite:'PCOL-Adrenergic_PCOL-26s_PTII_pptx.pdf slides 63, 67–73; Autonomic Nervous System.pdf slide 4; transcript 10/7',
 src:'both'},

{id:'sgc', term:'Soluble guanylyl cyclase (sGC)', lecture:'L11', group:'Nitric oxide',
 def:'The enzyme in the cytoplasm of vascular smooth muscle (floating free, not on the membrane like adenylate cyclase) that nitric oxide activates; it converts GTP into cyclic GMP, which causes vasodilation. Nitroglycerin’s nitric oxide goes straight to it, bypassing M3 and NOS.',
 gist:'Nitric oxide’s target in smooth muscle; it makes cyclic GMP.',
 scene:'Nitric oxide from nitroglycerin crosses into the smooth muscle and activates a free-floating enzyme in the cytoplasm that turns GTP into cyclic GMP.',
 confuse:['nos','pde'],
 quote:'activate the soluble granulase cyclase. So instead of having the AC, we have the JC, but it\'s not on the membrane, it\'s floating on the cytoplasma, and that\'s what makes cyclic GMP.',
 cite:'PCOL-Adrenergic_PCOL-26s_PTII_pptx.pdf slides 67–73; transcript 10/7',
 src:'both'},

{id:'cgmp', term:'cGMP (cyclic GMP)', lecture:'L11', group:'Nitric oxide',
 def:'The second messenger made by soluble guanylyl cyclase in smooth muscle when nitric oxide arrives; the more cGMP, the greater the vasodilation. It is broken down by phosphodiesterase (PDE), the same enzyme that breaks down cyclic AMP, so β2 and nitric oxide dilate vessels together.',
 gist:'Nitric oxide’s second messenger in smooth muscle; dilates, cleared by phosphodiesterase.',
 scene:'In the muscle layer of an artery a messenger made from GTP builds up after nitroglycerin, and the vessel widens until phosphodiesterase clears it.',
 confuse:['sgc','nitric-oxide'],
 quote:'It\'s going to get to the smooth muscle and it\'s going to increase the production of a second messenger called cyclic GMP. Very similar to cyclic AMP.',
 cite:'PCOL-Adrenergic_PCOL-26s_PTII_pptx.pdf slides 67–74; transcript 10/7',
 src:'both'},

{id:'pde', term:'Phosphodiesterase (PDE)', lecture:'L11', group:'Nitric oxide',
 def:'The enzyme that breaks down the second messengers cyclic AMP and cyclic GMP and so ends their signal (listed with adenylate cyclase as a regulator of cyclic AMP levels). In vascular smooth muscle it limits nitric oxide: the amount of nitric oxide made and the amount of PDE activity set how much the vessel dilates.',
 gist:'Enzyme that breaks down cyclic AMP and cyclic GMP, ending the signal.',
 scene:'After a nitrate dose the cyclic GMP in vascular smooth muscle is broken down within minutes by an enzyme, and the vessel returns to its tone.',
 confuse:['pde-inhibitor','sgc'],
 quote:'So the phosphodiesterase enzyme can break both cyclic EMP and cyclic GMP, our second messengers.',
 cite:'PCOL-Adrenergic_PCOL-26s_PTII_pptx.pdf slides 68–74; Autonomic Nervous System.pdf slide 7; transcript 10/7',
 src:'both'},

{id:'no-donor', term:'NO donor (nitrate)', lecture:'L11', group:'Nitric oxide',
 def:'A drug that is metabolized to give away nitric oxide: nitroglycerin, nitroprusside, isosorbide dinitrate and mononitrate (the “nitro” names). Its nitric oxide bypasses M3 and NOS and goes straight to soluble guanylyl cyclase, raising cGMP and dilating vessels; it replaces the nitric oxide a damaged endothelium can no longer make.',
 gist:'Metabolized to nitric oxide; skips M3 and the enzyme, straight to cyclic GMP.',
 scene:'A man with angina places nitroglycerin under his tongue; it breaks down and releases a gas that relaxes his coronary arteries without any receptor being activated.',
 confuse:['pde-inhibitor','nos'],
 quote:'It\'s either nitroglycerin or nitro pruide, so they are what we call nitric oxide donors. As these drugs get metabolized, they give away nitric oxide',
 cite:'PCOL-Adrenergic_PCOL-26s_PTII_pptx.pdf slides 62, 74; transcript 10/7',
 src:'both'},

{id:'pde-inhibitor', term:'PDE inhibitor (sildenafil)', lecture:'L11', group:'Nitric oxide',
 def:'A drug that blocks phosphodiesterase (sildenafil, tadalafil), so cGMP is not broken down and nitric oxide becomes more potent. Taken with nitroglycerin, which keeps supplying nitric oxide, the extra cGMP adds up and causes a marked, unsafe drop in blood pressure: the two must never be combined.',
 gist:'Stops cyclic GMP breakdown; with nitroglycerin, blood pressure falls dangerously.',
 scene:'A man who uses nitroglycerin for angina also takes an erectile-dysfunction pill, and his blood pressure drops so far that he collapses.',
 confuse:['no-donor','pde'],
 quote:'And I would like for you to tell me on an exam is why it\'s bad to take Sadenophil with a nitric oxide donor, right? Because you have this additive effect to the drugs.',
 cite:'PCOL-Adrenergic_PCOL-26s_PTII_pptx.pdf slide 74; transcript 10/7',
 src:'both'},

/* ---------------- RAAS ---------------- */
{id:'angiotensinogen', term:'Angiotensinogen', lecture:'L12', group:'RAAS',
 def:'The very long peptide made by the liver that circulates in the blood; an enzyme from the kidney cleaves it into angiotensin I, the first step of the renin–angiotensin–aldosterone system (RAAS). When a drug blocks the cascade further down, the body compensates upstream and makes more of it.',
 gist:'Liver-made long peptide in the blood; the first substrate of the cascade.',
 scene:'The liver releases a very long peptide into the blood, where an enzyme from the kidney cuts a small piece off it.',
 confuse:['renin','ang2'],
 quote:'But normally, we should be able to produce this very long peptide called angiotensinogen, and that\'s going to be coming from the liver.',
 cite:'PCOL-RAAS_26s.pdf slide 3; transcript 10/8',
 src:'both'},

{id:'renin', term:'Renin', lecture:'L12', group:'RAAS',
 def:'The enzyme made, stored and secreted by the granular juxtaglomerular cells of the renal afferent arteriole; it cleaves angiotensinogen into angiotensin I. Its release rises with low Na+/Cl− at the macula densa, low pressure in the kidney (intrarenal baroreceptors) and sympathetic β1 stimulation. Aliskiren inhibits it; β blockers lower its release.',
 gist:'Kidney enzyme from juxtaglomerular cells; cuts angiotensinogen into angiotensin I.',
 scene:'After a hemorrhage, low pressure at the kidney and extra sympathetic β1 firing make the juxtaglomerular cells secrete the enzyme that starts the cascade.',
 confuse:['ace','rate-limiting-enzyme'],
 quote:'renin is an enzyme that is gonna cleave or cut that that amino acid into a small chunk, and now we\'re gonna call that angiotensin one.',
 cite:'PCOL-RAAS_26s.pdf slides 3, 5–7; transcript 10/8',
 src:'both'},

{id:'rate-limiting-enzyme', term:'Rate-limiting enzyme (RLE)', lecture:'L12', group:'RAAS',
 def:'The first enzyme of a cascade, so blocking it lowers everything downstream: renin in the RAAS. Aliskiren (reversible, high affinity for plasma renin, low bioavailability) lowers plasma renin activity, angiotensin I, angiotensin II, AT1 and AT2 activation and aldosterone; only angiotensinogen rises upstream.',
 gist:'First step of the cascade: block it and everything downstream falls.',
 scene:'Aliskiren is taken for hypertension, and angiotensin I, angiotensin II and aldosterone all fall because the very first cut in the cascade is blocked.',
 confuse:['ace-inhibitor','arb'],
 quote:'So the rate limit enzyme is the first one, right? So if you block that, everything downstream from that goes down because you\'re missing the first crucial step to make the processes.',
 cite:'PCOL-RAAS_26s.pdf slide 8; transcript 10/8',
 src:'both'},

{id:'ace', term:'ACE (angiotensin-converting enzyme)', lecture:'L12', group:'RAAS',
 def:'The enzyme (bound and unbound) that converts inactive angiotensin I into active angiotensin II within milliseconds; it also breaks down bradykinin, a potent vasodilator. The -pril drugs block both of its jobs.',
 gist:'Converts the inactive peptide into the active one and degrades bradykinin.',
 scene:'Within milliseconds of forming, an inactive peptide is cut into the active vasoconstrictor, and the same protein also destroys bradykinin.',
 confuse:['renin','bradykinin'],
 quote:'For the longest time we thought that ANG1 and H2 were two active peptides, but A1 is converted to H2 like in no tomorrow, like within milliseconds. And that occurs by the angiotensin converting enzyme or the ACE enzyme.',
 cite:'PCOL-RAAS_26s.pdf slides 3, 9; transcript 10/8',
 src:'both'},

{id:'ang2', term:'Ang II (angiotensin II)', lecture:'L12', group:'RAAS',
 def:'The active peptide of the cascade. Binding mainly AT1 (“9 out of 10”), it constricts arteries and veins directly, increases Na+ reabsorption in the renal tubules, stimulates synthesis and release of aldosterone from the adrenal cortex, decreases renal blood flow, and over time causes remodeling (hypertrophy of vascular and cardiac cells, collagen deposition).',
 gist:'The active peptide: constricts vessels, retains sodium, releases aldosterone, remodels.',
 scene:'After blood loss a peptide made within milliseconds constricts arteries and veins, holds sodium and water and raises aldosterone, so the skin turns pale and cold.',
 confuse:['at1','aldosterone'],
 quote:'Now, angiotensin 2 has two options to who wants to bind and interact with. It has the highest affinity for the AT1 receptor.',
 cite:'PCOL-RAAS_26s.pdf slides 3, 15–17; transcript 10/8',
 src:'both'},

{id:'at1', term:'AT1 (angiotensin type 1 receptor)', lecture:'L12', group:'RAAS',
 def:'The receptor angiotensin II prefers, coupled to Gq (more Ca++): vasoconstriction, more Na+ reabsorption, more aldosterone and more remodeling. The -sartans (ARBs) block it with about 10,000-fold higher affinity than for AT2.',
 gist:'Gq: calcium up, vessels constrict, sodium kept, aldosterone up; sartans block it.',
 scene:'Losartan occupies the Gq-coupled site on arterial smooth muscle that the active peptide prefers, so the vessel no longer constricts and aldosterone falls.',
 confuse:['at2','alpha1'],
 quote:'And if I tell that angiotensin type 1 is called to GQ, what do you think it\'s going to do? Something positive or something negative. Something positive because remember GQ increases calcium',
 cite:'PCOL-RAAS_26s.pdf slides 3, 13, 18; transcript 10/8',
 src:'both'},

{id:'at2', term:'AT2 (angiotensin type 2 receptor)', lecture:'L12', group:'RAAS',
 def:'The second angiotensin II receptor, coupled to Gi (less cyclic AMP), with effects opposite to AT1: vasodilation, Na+ excretion, less remodeling. It is the physiological antagonist of AT1. No drug activates it directly; ARBs raise its activation (more angiotensin II, AT1 blocked), while ACE inhibitors and aliskiren lower it.',
 gist:'Gi: dilates and excretes sodium, opposing AT1; sartans increase its activation.',
 scene:'A patient on valsartan has more of the active peptide in the blood, and because only AT1 is blocked, the Gi-coupled site that dilates vessels is activated more.',
 confuse:['at1','arb'],
 quote:'The AT2 is called to a G alphai. So what do you think it\'s going to do? The opposite of the AT1. So this is our physiological antagonist.',
 cite:'PCOL-RAAS_26s.pdf slides 3, 18, 26–27; transcript 10/8',
 src:'both'},

{id:'aldosterone', term:'Aldosterone', lecture:'L12', group:'RAAS',
 def:'The hormone from the adrenal gland (released when angiotensin II stimulates it) that binds the mineralocorticoid receptor (MR), a nuclear receptor in the late distal tubule and collecting duct. More Na+ channels, K+ channels and Na+/K+-ATPase are made, so Na+ (and water) is retained at the cost of K+: a K+-wasting hormone.',
 gist:'Adrenal hormone on a nuclear receptor: keeps sodium, wastes K+.',
 scene:'A hormone from the adrenal cortex enters collecting-duct cells and turns on genes for sodium channels and pumps; sodium is kept and potassium is lost in the urine.',
 confuse:['potassium-sparing','mr'],
 quote:'So the more aldosterone you have, the more channels you\'re going to produce, the more pumps you\'re going to make, and thus give you the chance to retain more sodium at the cost of losing what potassium. So aldosterone is a potassium wasting hormone.',
 cite:'PCOL-RAAS_26s.pdf slides 15, 20–21; transcript 10/8',
 src:'both'},

{id:'mr', term:'MR (mineralocorticoid receptor)', lecture:'L12', group:'RAAS',
 def:'The nuclear receptor that aldosterone binds in the kidney (late distal tubule and collecting duct): it changes messenger RNA production to make more Na+ channels, K+ channels and Na+/K+-ATPase. In the heart and vasculature its activation is thought to add fibrosis. Spironolactone and eplerenone block it.',
 gist:'Nuclear target in the collecting duct; switches on sodium channels and pumps.',
 scene:'Spironolactone outcompetes the adrenal hormone at its nuclear target in collecting-duct cells, fewer sodium channels are made, and potassium stays in the blood.',
 confuse:['aldosterone','at1'],
 quote:'Aldosterone is going to bind to the immunocord cord receptor, the MR receptor. This is a nuclear receptor, which means it\'s going to change your messenger RNA formation to code for more pumps and more channels.',
 cite:'PCOL-RAAS_26s.pdf slides 20–21; transcript 10/8',
 src:'both'},

{id:'potassium-sparing', term:'Potassium-sparing diuretic (MR antagonist)', lecture:'L12', group:'RAAS',
 def:'An aldosterone receptor blocker: spironolactone (also a weak inhibitor of the androgen receptor and of testosterone synthesis: gynecomastia and impotence in men; used for hirsutism in women) and eplerenone (selective for the kidney MR, without those effects). Blocking the mineralocorticoid receptor in the late distal tubule and collecting duct loses Na+ and keeps K+, so hyperkalemia is its main adverse effect.',
 gist:'Blocks aldosterone’s receptor: sodium lost, K+ kept; spironolactone, eplerenone.',
 scene:'A man with heart failure takes spironolactone; his sodium and water output rises, his serum K+ creeps toward 5.5, and his breasts become tender.',
 confuse:['aldosterone','hyperkalemia'],
 quote:'those drugs are going to be potassium sparing diuretics because you\'re going to lose the sodium and spare the potassium.',
 cite:'PCOL-RAAS_26s.pdf slides 21–22; transcript 10/8',
 src:'both'},

{id:'bradykinin', term:'Bradykinin', lecture:'L12', group:'RAAS',
 def:'A potent vasodilator peptide that ACE normally breaks down. ACE inhibitors raise it (their secondary mechanism, with more prostaglandins), adding vasodilation; its accumulation causes their dry cough (5–20% of patients, between 1 week and 6 months) and angioedema.',
 gist:'Vasodilator peptide the converting enzyme destroys; buildup gives dry cough and angioedema.',
 scene:'Two weeks after starting lisinopril a patient develops a dry, nagging cough from a vasodilator peptide the drug stopped from being broken down.',
 confuse:['ace','at2'],
 quote:'Bradykinin is a very potent vasodilator, so you get this bonus effect. You\'re not only stopping the constrictor being made, but also enhancing the potent vasodilator production because you\'re stopping from it breaking down it.',
 cite:'PCOL-RAAS_26s.pdf slides 9, 12, 19; transcript 10/8',
 src:'both'},

{id:'hyperkalemia', term:'Hyperkalemia', lecture:'L12', group:'RAAS',
 def:'Too much potassium in the blood (normal about 3 to 5). A shared adverse effect of the drugs that weaken aldosterone’s action: renin inhibitors, ACE inhibitors and ARBs (worse in renal compromise) and the MR antagonists spironolactone and eplerenone. Succinylcholine also causes it (muscle cells lose K+).',
 gist:'Too much potassium in the blood; every drug that weakens aldosterone can cause it.',
 scene:'A patient with kidney disease whose potassium is already 5.5 is started on lisinopril and spironolactone, and the next lab value is higher still.',
 confuse:['potassium-sparing','bradykinin'],
 quote:'Hopefully pick E, all the above, because the spironolactone definitely, right? Because that\'s the potassium sparing diuretic. But remember that both the ACEs, the ARBs, and the RAIN inhibitors can also cause hyperkalemia.',
 cite:'PCOL-RAAS_26s.pdf slides 19, 22; PCOL-NMJ_PCOL_2026s_pptx.pdf slide 25; transcript 10/5; transcript 10/8',
 src:'both'},

{id:'ace-inhibitor', term:'ACE inhibitor', lecture:'L12', group:'RAAS',
 def:'A first-line, selective, reversible blocker of ACE (captopril, enalapril, lisinopril: any drug ending in -pril). Primary mechanism: less angiotensin I converted to angiotensin II, so angiotensin II, AT1 and AT2 activation and aldosterone fall while angiotensin I and angiotensinogen rise. Secondary: bradykinin is not broken down (more vasodilation, dry cough, angioedema).',
 gist:'Blocks the converting step: active peptide down, bradykinin up, dry cough.',
 scene:'Lisinopril is started: angiotensin I builds up in the blood, angiotensin II and aldosterone fall, and bradykinin accumulates.',
 confuse:['arb','rate-limiting-enzyme'],
 quote:'So, what is that you must know for the exam, that anything with the Perl doesn\'t matter which of the 11 ACE inhibitors that you have, it\'s gonna be what? AC ACE inhibitor, right?',
 cite:'PCOL-RAAS_26s.pdf slides 4, 9–12, 19; transcript 10/8',
 src:'both'},

{id:'arb', term:'ARB (angiotensin II receptor blocker)', lecture:'L12', group:'RAAS',
 def:'A reversible, selective AT1 antagonist with about 10,000-fold higher affinity for AT1 than AT2 (losartan, valsartan: any drug ending in -sartan). AT1 activation falls while angiotensin I and II rise (the body compensates) and AT2 activation rises, leaving the physiological antagonist free. It does not touch bradykinin, so it causes less cough than the -prils.',
 gist:'Blocks only AT1, so the peptide rises and AT2 is activated more; sartans.',
 scene:'A patient whose lisinopril cough was intolerable switches to losartan; AT1 is blocked, the active peptide climbs, and the Gi-coupled subtype is activated more.',
 confuse:['ace-inhibitor','at2'],
 quote:'It doesn\'t matter what sartan you have. So as long as you know one, you know them all',
 cite:'PCOL-RAAS_26s.pdf slides 4, 13–14, 26–27; transcript 10/8',
 src:'both'}
];
